    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 72-year-old female is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Mupirocin ointment", "Intravenous Ampicillin", "Topical Ketoconazole cream", "Oral Vancomycin", "Oral Cephalexin"]'::jsonb, 0, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 17-year-old female is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Scarlet Fever", "Streptococcal toxic shock syndrome", "Acute glomerulonephritis and carditis", "Acute Rheumatic Fever (ARF)", "Post-streptococcal Glomerulonephritis (PSGN)"]'::jsonb, 4, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 25-year-old woman toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["BP180 (Type XVII Collagen)", "Desmocollin 1", "Desmoglein 3", "Desmoglein 1", "Type VII Collagen"]'::jsonb, 3, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless girl presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Necrotizing Fasciitis", "Erysipelas", "Non-bullous Impetigo", "Pyoderma Gangrenosum", "Ecthyma"]'::jsonb, 4, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 38-year-old female presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Staphylococcus aureus", "Pseudomonas aeruginosa", "Mycobacterium marinum", "Streptococcus pyogenes (Group A Strep)", "Bartonella henselae"]'::jsonb, 3, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 62-year-old girl with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["The presence of prominent lymphatic streaking", "Successful treatment with penicillin instead of cephalexin", "The presence of high fever and leukocytosis", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The rapid, hyperacute spread within hours"]'::jsonb, 3, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 25-year-old boy presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin", "Apply high-potency topical steroids to reduce local inflammation", "Order an urgent MRI of the left lower extremity with contrast", "Obtain double-volume blood cultures and wait for the results", "Emergent surgical consultation for exploratory debridement"]'::jsonb, 4, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 38-year-old man complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Candida albicans", "Corynebacterium minutissimum", "Malassezia furfur", "Trichophyton rubrum", "Staphylococcus aureus"]'::jsonb, 1, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 72-year-old male athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Mechanical erosion from repetitive friction and hyperhidrosis", "Superficial invasion of dermatophytes into the sweat glands", "Bacterial production of extracellular proteases that digest the stratum corneum", "Autoimmune-mediated destruction of plantar sweat ducts", "A chronic contact allergy to rubber compounds in athletic shoes"]'::jsonb, 2, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 38-year-old man develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is highly contagious and spreads to family members through air droplets", "It leads to chronic, scarred alopecia of the affected hair follicles", "It is caused by a type IV hypersensitivity reaction to chlorine", "It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia"]'::jsonb, 3, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 25-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Oral Griseofulvin", "Ciprofloxacin or Doxycycline", "Topical Permethrin 5% cream", "Oral Valacyclovir", "Intravenous Ganciclovir"]'::jsonb, 1, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Candida albicans", "Trichophyton rubrum", "Trichophyton tonsurans", "Microsporum canis", "Malassezia furfur"]'::jsonb, 2, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Ketoconazole 2% shampoo daily", "Topical Clobetasol propionate ointment", "Oral Amoxicillin-Clavulanate", "Oral Griseofulvin or oral Terbinafine", "Topical Terbinafine 1% cream"]'::jsonb, 3, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["A neoplastic proliferation of follicular dendritic cells", "Direct fungal invasion into the meninges and skull bone", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)", "A congenital vascular malformation triggered by inflammation"]'::jsonb, 2, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 45-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Trichophyton tonsurans", "Malassezia furfur", "Microsporum canis", "Trichophyton rubrum", "Candida albicans"]'::jsonb, 3, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Tinea cruris is never itchy, while Candidiasis is extremely painful", "Tinea cruris presents with satellite pustules, whereas Candidiasis does not", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast"]'::jsonb, 0, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 78-year-old man presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The scalp for black dot alopecia", "The fingernails of the non-dominant hand", "The axillae for coral-red fluorescence", "The oral cavity for white plaques", "The palms of the hands (typically only one palm is affected)"]'::jsonb, 4, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 50-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Majocchi''s Granuloma", "Kerion", "Sporotrichosis", "Cellulitis", "Erythema Nodosum"]'::jsonb, 0, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old woman presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored", "1 week of oral Terbinafine; no monitoring is required", "12 months of oral Terbinafine; CBC must be monitored weekly", "12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "6 weeks of oral Terbinafine; no laboratory monitoring is required"]'::jsonb, 0, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young male returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Coproporphyrin III", "Azelaic acid", "Lactic acid", "Uric acid", "Melanin"]'::jsonb, 1, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Gram-positive rods in chains", "Spherules containing endospores", "Pseudohyphae and budding yeast cells", "Henderson-Paterson bodies", "Branching, septate hyphae"]'::jsonb, 2, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin", "Herpes Simplex Virus; oral Acyclovir", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals", "Pseudomonas aeruginosa; soak in diluted bleach daily", "Trichophyton rubrum; oral Terbinafine for 12 weeks"]'::jsonb, 2, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 50-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Leishmaniasis", "Blastomycosis", "Cutaneous Anthrax", "Sporotrichosis", "Majocchi''s Granuloma"]'::jsonb, 3, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old man recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Tinea Versicolor", "Sporotrichosis", "Blastomycosis", "Histoplasmosis", "Coccidioidomycosis"]'::jsonb, 4, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 28-year-old male from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Blastomyces dermatitidis", "Histoplasma capsulatum", "Candida albicans", "Coccidioides immitis", "Sporothrix schenckii"]'::jsonb, 0, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Public swimming pools and fish tanks", "Soil contaminated with bird or bat droppings (caves, chicken coops)", "Decaying wood and organic matter near rivers", "Infected sheep and livestock", "Arid desert sand of the Southwest US"]'::jsonb, 1, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 72-year-old boy presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Eczema Herpeticum (Kaposi varicelliform eruption)", "Toxic Epidermal Necrolysis (TEN)", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Disseminated Molluscum Contagiosum", "Bullous Impetigo"]'::jsonb, 0, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 19-year-old boy presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Keratinocytes of the basal epidermis", "Splenic macrophages", "Trigeminal ganglion", "Dorsal root ganglion (Sensory nerve ganglion)", "Langerhans cells in the dermis"]'::jsonb, 3, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old male presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Koebner sign; it indicates the shingles was triggered by local scratching", "Henderson sign; it indicates a poxvirus superinfection", "Nikolsky sign; it indicates severe epidermal detachment and SJS", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss"]'::jsonb, 3, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Meniere''s disease with HSV-1 outbreak", "Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Bell''s palsy with secondary ear infection", "Nicolau Syndrome", "Gorlin Syndrome"]'::jsonb, 1, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes", "Massive pseudoepitheliomatous hyperplasia with microabscesses", "Multinucleated giant cells with ballooning degeneration of the epidermis", "Acantholysis with a ''fishnet'' immunofluorescence pattern", "A dense septal panniculitis without vasculitis"]'::jsonb, 0, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Sites of focal melanin deposition within the basal layer", "Trap-door collection of dirt and environmental debris", "Necrotic nuclei of basal cells killed by the HPV virus", "Viral spores embedded in the stratum corneum", "Thrombosed, clotted capillaries supplying the rapidly growing wart tissue"]'::jsonb, 4, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["There is no reliable clinical difference; a biopsy is always required", "Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure", "Calluses show pinpoint bleeding upon paring and are only painful with direct pressure", "Warts are soft and fluctuant, whereas calluses are rock-hard", "Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not"]'::jsonb, 1, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Human Papillomavirus", "Orf virus (a parapoxvirus)", "Herpes Simplex Virus", "Bacillus anthracis", "Coxsackievirus A16"]'::jsonb, 1, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Parvovirus B19; aplastic crisis in healthy children", "Herpes Simplex Virus 1; permanent scarring alopecia", "Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "HHV-6; febrile seizures leading to epilepsy", "Sarcoptes scabiei; post-infectious glomerulonephritis"]'::jsonb, 2, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "Coxsackievirus A16; causing severe viral meningitis", "HHV-6; inducing status epilepticus", "Parvovirus B19; precipitating an acute Aplastic Crisis", "Streptococcus pyogenes; leading to acute rheumatic fever"]'::jsonb, 3, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Scarlet Fever", "Rubella (German Measles)", "Erythema Infectiosum (Fifth Disease)", "Rubeola (Measles)", "Roseola Infantum (Exanthem Subitum)"]'::jsonb, 4, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Ketoconazole 2% cream; applied to the trunk and limbs for 3 days", "Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours"]'::jsonb, 4, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Strict isolation and daily washing with soap and water", "Topical Permethrin 5% cream alone applied once", "High-dose intravenous antibiotics and surgical debridement of the scales", "Oral Griseofulvin for 12 weeks", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream"]'::jsonb, 4, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Ancylostoma braziliense (animal hookworm)", "Leishmania tropica", "Strongyloides stercoralis", "Sarcoptes scabiei", "Dracunculus medinensis"]'::jsonb, 0, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse", "A congenital vascular anomaly flared by the infestation", "Deep dermal deposition of blue melanin pigment by activated melanocytes", "Localized vascular thrombosis in the superficial capillaries caused by scratching", "A secondary deep fungal infection within the pubic follicles"]'::jsonb, 0, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Contact with contaminated sheep or goats", "Bite of an infected Ixodes Tick", "Bite of an infected Phlebotomine Sandfly", "Inhalation of dry bird droppings", "Barefoot contact with beach sand"]'::jsonb, 2, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Sarcoptes scabiei (Scabies)", "Ixodes scapularis (Ticks)", "Pthirus pubis (Pubic lice)", "Ancylostoma braziliense (Hookworm)", "Cimex lectularius (Bedbugs)"]'::jsonb, 4, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 25-year-old female who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Cutaneous Leishmaniasis", "Sporotrichosis", "Erysipeloid", "Blastomycosis"]'::jsonb, 0, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 28-year-old male is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Mupirocin ointment", "Oral Cephalexin", "Intravenous Ampicillin", "Oral Vancomycin", "Topical Ketoconazole cream"]'::jsonb, 0, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 68-year-old male is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Acute Rheumatic Fever (ARF)", "Acute glomerulonephritis and carditis", "Streptococcal toxic shock syndrome", "Post-streptococcal Glomerulonephritis (PSGN)", "Scarlet Fever"]'::jsonb, 3, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 25-year-old woman toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["Desmoglein 1", "BP180 (Type XVII Collagen)", "Desmocollin 1", "Type VII Collagen", "Desmoglein 3"]'::jsonb, 0, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless female presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Non-bullous Impetigo", "Erysipelas", "Ecthyma", "Pyoderma Gangrenosum", "Necrotizing Fasciitis"]'::jsonb, 2, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 55-year-old boy presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Mycobacterium marinum", "Streptococcus pyogenes (Group A Strep)", "Staphylococcus aureus", "Pseudomonas aeruginosa", "Bartonella henselae"]'::jsonb, 1, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 12-year-old woman with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["Successful treatment with penicillin instead of cephalexin", "The presence of prominent lymphatic streaking", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The presence of high fever and leukocytosis", "The rapid, hyperacute spread within hours"]'::jsonb, 2, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 78-year-old girl presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Order an urgent MRI of the left lower extremity with contrast", "Obtain double-volume blood cultures and wait for the results", "Emergent surgical consultation for exploratory debridement", "Apply high-potency topical steroids to reduce local inflammation", "Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin"]'::jsonb, 2, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 78-year-old girl complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Trichophyton rubrum", "Candida albicans", "Staphylococcus aureus", "Corynebacterium minutissimum", "Malassezia furfur"]'::jsonb, 3, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 68-year-old girl athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Mechanical erosion from repetitive friction and hyperhidrosis", "Superficial invasion of dermatophytes into the sweat glands", "Autoimmune-mediated destruction of plantar sweat ducts", "Bacterial production of extracellular proteases that digest the stratum corneum", "A chronic contact allergy to rubber compounds in athletic shoes"]'::jsonb, 3, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 62-year-old female develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It leads to chronic, scarred alopecia of the affected hair follicles", "It is highly contagious and spreads to family members through air droplets", "It is caused by a type IV hypersensitivity reaction to chlorine", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia"]'::jsonb, 0, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 45-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Ciprofloxacin or Doxycycline", "Oral Griseofulvin", "Oral Valacyclovir", "Intravenous Ganciclovir", "Topical Permethrin 5% cream"]'::jsonb, 0, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Trichophyton rubrum", "Malassezia furfur", "Microsporum canis", "Candida albicans", "Trichophyton tonsurans"]'::jsonb, 4, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Oral Griseofulvin or oral Terbinafine", "Topical Terbinafine 1% cream", "Topical Clobetasol propionate ointment", "Oral Amoxicillin-Clavulanate", "Topical Ketoconazole 2% shampoo daily"]'::jsonb, 0, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["A congenital vascular malformation triggered by inflammation", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "A neoplastic proliferation of follicular dendritic cells", "Direct fungal invasion into the meninges and skull bone", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)"]'::jsonb, 1, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 25-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Microsporum canis", "Trichophyton tonsurans", "Malassezia furfur", "Trichophyton rubrum", "Candida albicans"]'::jsonb, 3, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Tinea cruris presents with satellite pustules, whereas Candidiasis does not", "Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast", "Tinea cruris is never itchy, while Candidiasis is extremely painful", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting"]'::jsonb, 1, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 55-year-old man presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The fingernails of the non-dominant hand", "The oral cavity for white plaques", "The scalp for black dot alopecia", "The palms of the hands (typically only one palm is affected)", "The axillae for coral-red fluorescence"]'::jsonb, 3, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 25-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Sporotrichosis", "Cellulitis", "Kerion", "Erythema Nodosum", "Majocchi''s Granuloma"]'::jsonb, 4, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old male presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["1 week of oral Terbinafine; no monitoring is required", "12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "6 weeks of oral Terbinafine; no laboratory monitoring is required", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored", "12 months of oral Terbinafine; CBC must be monitored weekly"]'::jsonb, 3, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young male returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Lactic acid", "Coproporphyrin III", "Uric acid", "Azelaic acid", "Melanin"]'::jsonb, 3, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Henderson-Paterson bodies", "Spherules containing endospores", "Gram-positive rods in chains", "Pseudohyphae and budding yeast cells", "Branching, septate hyphae"]'::jsonb, 3, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Herpes Simplex Virus; oral Acyclovir", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals", "Trichophyton rubrum; oral Terbinafine for 12 weeks", "Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin", "Pseudomonas aeruginosa; soak in diluted bleach daily"]'::jsonb, 1, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 62-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Blastomycosis", "Cutaneous Anthrax", "Leishmaniasis", "Majocchi''s Granuloma", "Sporotrichosis"]'::jsonb, 4, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old male recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Coccidioidomycosis", "Blastomycosis", "Sporotrichosis", "Histoplasmosis", "Tinea Versicolor"]'::jsonb, 0, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 35-year-old man from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Histoplasma capsulatum", "Sporothrix schenckii", "Candida albicans", "Blastomyces dermatitidis", "Coccidioides immitis"]'::jsonb, 3, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Public swimming pools and fish tanks", "Arid desert sand of the Southwest US", "Soil contaminated with bird or bat droppings (caves, chicken coops)", "Infected sheep and livestock", "Decaying wood and organic matter near rivers"]'::jsonb, 2, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 19-year-old boy presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Eczema Herpeticum (Kaposi varicelliform eruption)", "Toxic Epidermal Necrolysis (TEN)", "Bullous Impetigo", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Disseminated Molluscum Contagiosum"]'::jsonb, 0, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 62-year-old girl presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Langerhans cells in the dermis", "Dorsal root ganglion (Sensory nerve ganglion)", "Keratinocytes of the basal epidermis", "Trigeminal ganglion", "Splenic macrophages"]'::jsonb, 1, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old boy presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Henderson sign; it indicates a poxvirus superinfection", "Koebner sign; it indicates the shingles was triggered by local scratching", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement", "Nikolsky sign; it indicates severe epidermal detachment and SJS", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss"]'::jsonb, 2, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Meniere''s disease with HSV-1 outbreak", "Gorlin Syndrome", "Bell''s palsy with secondary ear infection", "Nicolau Syndrome"]'::jsonb, 0, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Massive pseudoepitheliomatous hyperplasia with microabscesses", "Acantholysis with a ''fishnet'' immunofluorescence pattern", "A dense septal panniculitis without vasculitis", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes", "Multinucleated giant cells with ballooning degeneration of the epidermis"]'::jsonb, 3, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Viral spores embedded in the stratum corneum", "Necrotic nuclei of basal cells killed by the HPV virus", "Trap-door collection of dirt and environmental debris", "Sites of focal melanin deposition within the basal layer", "Thrombosed, clotted capillaries supplying the rapidly growing wart tissue"]'::jsonb, 4, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["Warts are soft and fluctuant, whereas calluses are rock-hard", "Calluses show pinpoint bleeding upon paring and are only painful with direct pressure", "Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure", "There is no reliable clinical difference; a biopsy is always required", "Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not"]'::jsonb, 2, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Human Papillomavirus", "Herpes Simplex Virus", "Bacillus anthracis", "Coxsackievirus A16", "Orf virus (a parapoxvirus)"]'::jsonb, 4, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Parvovirus B19; aplastic crisis in healthy children", "HHV-6; febrile seizures leading to epilepsy", "Sarcoptes scabiei; post-infectious glomerulonephritis", "Herpes Simplex Virus 1; permanent scarring alopecia", "Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later"]'::jsonb, 4, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "Parvovirus B19; precipitating an acute Aplastic Crisis", "HHV-6; inducing status epilepticus", "Streptococcus pyogenes; leading to acute rheumatic fever", "Coxsackievirus A16; causing severe viral meningitis"]'::jsonb, 1, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Rubella (German Measles)", "Rubeola (Measles)", "Scarlet Fever", "Roseola Infantum (Exanthem Subitum)", "Erythema Infectiosum (Fifth Disease)"]'::jsonb, 3, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours", "Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes", "Ketoconazole 2% cream; applied to the trunk and limbs for 3 days"]'::jsonb, 1, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Oral Griseofulvin for 12 weeks", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream", "High-dose intravenous antibiotics and surgical debridement of the scales", "Strict isolation and daily washing with soap and water", "Topical Permethrin 5% cream alone applied once"]'::jsonb, 1, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Leishmania tropica", "Ancylostoma braziliense (animal hookworm)", "Dracunculus medinensis", "Sarcoptes scabiei", "Strongyloides stercoralis"]'::jsonb, 1, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["Localized vascular thrombosis in the superficial capillaries caused by scratching", "A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse", "A secondary deep fungal infection within the pubic follicles", "Deep dermal deposition of blue melanin pigment by activated melanocytes", "A congenital vascular anomaly flared by the infestation"]'::jsonb, 1, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Bite of an infected Phlebotomine Sandfly", "Contact with contaminated sheep or goats", "Inhalation of dry bird droppings", "Barefoot contact with beach sand", "Bite of an infected Ixodes Tick"]'::jsonb, 0, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Ancylostoma braziliense (Hookworm)", "Pthirus pubis (Pubic lice)", "Cimex lectularius (Bedbugs)", "Ixodes scapularis (Ticks)", "Sarcoptes scabiei (Scabies)"]'::jsonb, 2, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 50-year-old female who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Blastomycosis", "Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Erysipeloid", "Cutaneous Leishmaniasis", "Sporotrichosis"]'::jsonb, 1, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 38-year-old man is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Oral Vancomycin", "Oral Cephalexin", "Intravenous Ampicillin", "Topical Mupirocin ointment", "Topical Ketoconazole cream"]'::jsonb, 3, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 62-year-old girl is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Scarlet Fever", "Streptococcal toxic shock syndrome", "Acute Rheumatic Fever (ARF)", "Post-streptococcal Glomerulonephritis (PSGN)", "Acute glomerulonephritis and carditis"]'::jsonb, 3, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 72-year-old female toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["Desmocollin 1", "Desmoglein 1", "Desmoglein 3", "Type VII Collagen", "BP180 (Type XVII Collagen)"]'::jsonb, 1, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless male presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Pyoderma Gangrenosum", "Erysipelas", "Necrotizing Fasciitis", "Non-bullous Impetigo", "Ecthyma"]'::jsonb, 4, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 50-year-old woman presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Pseudomonas aeruginosa", "Bartonella henselae", "Mycobacterium marinum", "Streptococcus pyogenes (Group A Strep)", "Staphylococcus aureus"]'::jsonb, 3, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 35-year-old man with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["The presence of high fever and leukocytosis", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The presence of prominent lymphatic streaking", "The rapid, hyperacute spread within hours", "Successful treatment with penicillin instead of cephalexin"]'::jsonb, 1, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 17-year-old woman presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Obtain double-volume blood cultures and wait for the results", "Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin", "Emergent surgical consultation for exploratory debridement", "Order an urgent MRI of the left lower extremity with contrast", "Apply high-potency topical steroids to reduce local inflammation"]'::jsonb, 2, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 12-year-old boy complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Staphylococcus aureus", "Trichophyton rubrum", "Corynebacterium minutissimum", "Candida albicans", "Malassezia furfur"]'::jsonb, 2, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 78-year-old woman athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Mechanical erosion from repetitive friction and hyperhidrosis", "Autoimmune-mediated destruction of plantar sweat ducts", "Superficial invasion of dermatophytes into the sweat glands", "Bacterial production of extracellular proteases that digest the stratum corneum", "A chronic contact allergy to rubber compounds in athletic shoes"]'::jsonb, 3, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 25-year-old girl develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia", "It is caused by a type IV hypersensitivity reaction to chlorine", "It is highly contagious and spreads to family members through air droplets", "It leads to chronic, scarred alopecia of the affected hair follicles"]'::jsonb, 0, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 35-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Topical Permethrin 5% cream", "Ciprofloxacin or Doxycycline", "Oral Griseofulvin", "Intravenous Ganciclovir", "Oral Valacyclovir"]'::jsonb, 1, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Trichophyton tonsurans", "Malassezia furfur", "Candida albicans", "Trichophyton rubrum", "Microsporum canis"]'::jsonb, 0, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Oral Amoxicillin-Clavulanate", "Oral Griseofulvin or oral Terbinafine", "Topical Terbinafine 1% cream", "Topical Ketoconazole 2% shampoo daily", "Topical Clobetasol propionate ointment"]'::jsonb, 1, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["Direct fungal invasion into the meninges and skull bone", "A neoplastic proliferation of follicular dendritic cells", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "A congenital vascular malformation triggered by inflammation", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)"]'::jsonb, 2, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 45-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Trichophyton rubrum", "Trichophyton tonsurans", "Candida albicans", "Microsporum canis", "Malassezia furfur"]'::jsonb, 0, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Tinea cruris presents with satellite pustules, whereas Candidiasis does not", "Tinea cruris is never itchy, while Candidiasis is extremely painful", "Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum"]'::jsonb, 4, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 68-year-old female presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The palms of the hands (typically only one palm is affected)", "The scalp for black dot alopecia", "The fingernails of the non-dominant hand", "The oral cavity for white plaques", "The axillae for coral-red fluorescence"]'::jsonb, 0, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 19-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Erythema Nodosum", "Sporotrichosis", "Kerion", "Majocchi''s Granuloma", "Cellulitis"]'::jsonb, 3, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old man presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "1 week of oral Terbinafine; no monitoring is required", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored", "12 months of oral Terbinafine; CBC must be monitored weekly", "6 weeks of oral Terbinafine; no laboratory monitoring is required"]'::jsonb, 2, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young male returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Lactic acid", "Azelaic acid", "Melanin", "Coproporphyrin III", "Uric acid"]'::jsonb, 1, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Spherules containing endospores", "Branching, septate hyphae", "Henderson-Paterson bodies", "Pseudohyphae and budding yeast cells", "Gram-positive rods in chains"]'::jsonb, 3, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin", "Pseudomonas aeruginosa; soak in diluted bleach daily", "Herpes Simplex Virus; oral Acyclovir", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals", "Trichophyton rubrum; oral Terbinafine for 12 weeks"]'::jsonb, 3, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 25-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Leishmaniasis", "Cutaneous Anthrax", "Blastomycosis", "Sporotrichosis", "Majocchi''s Granuloma"]'::jsonb, 3, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old woman recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Sporotrichosis", "Coccidioidomycosis", "Histoplasmosis", "Tinea Versicolor", "Blastomycosis"]'::jsonb, 1, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 55-year-old man from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Candida albicans", "Histoplasma capsulatum", "Sporothrix schenckii", "Blastomyces dermatitidis", "Coccidioides immitis"]'::jsonb, 3, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Soil contaminated with bird or bat droppings (caves, chicken coops)", "Public swimming pools and fish tanks", "Arid desert sand of the Southwest US", "Decaying wood and organic matter near rivers", "Infected sheep and livestock"]'::jsonb, 0, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 35-year-old woman presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Toxic Epidermal Necrolysis (TEN)", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Eczema Herpeticum (Kaposi varicelliform eruption)", "Bullous Impetigo", "Disseminated Molluscum Contagiosum"]'::jsonb, 2, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 28-year-old boy presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Trigeminal ganglion", "Keratinocytes of the basal epidermis", "Splenic macrophages", "Dorsal root ganglion (Sensory nerve ganglion)", "Langerhans cells in the dermis"]'::jsonb, 3, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old male presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Nikolsky sign; it indicates severe epidermal detachment and SJS", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss", "Henderson sign; it indicates a poxvirus superinfection", "Koebner sign; it indicates the shingles was triggered by local scratching"]'::jsonb, 1, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Meniere''s disease with HSV-1 outbreak", "Bell''s palsy with secondary ear infection", "Gorlin Syndrome", "Nicolau Syndrome"]'::jsonb, 0, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["A dense septal panniculitis without vasculitis", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes", "Massive pseudoepitheliomatous hyperplasia with microabscesses", "Multinucleated giant cells with ballooning degeneration of the epidermis", "Acantholysis with a ''fishnet'' immunofluorescence pattern"]'::jsonb, 1, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Viral spores embedded in the stratum corneum", "Sites of focal melanin deposition within the basal layer", "Necrotic nuclei of basal cells killed by the HPV virus", "Trap-door collection of dirt and environmental debris", "Thrombosed, clotted capillaries supplying the rapidly growing wart tissue"]'::jsonb, 4, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["Calluses show pinpoint bleeding upon paring and are only painful with direct pressure", "There is no reliable clinical difference; a biopsy is always required", "Warts are soft and fluctuant, whereas calluses are rock-hard", "Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not", "Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure"]'::jsonb, 4, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Orf virus (a parapoxvirus)", "Human Papillomavirus", "Coxsackievirus A16", "Bacillus anthracis", "Herpes Simplex Virus"]'::jsonb, 0, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Parvovirus B19; aplastic crisis in healthy children", "Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "Sarcoptes scabiei; post-infectious glomerulonephritis", "Herpes Simplex Virus 1; permanent scarring alopecia", "HHV-6; febrile seizures leading to epilepsy"]'::jsonb, 1, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["HHV-6; inducing status epilepticus", "Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "Parvovirus B19; precipitating an acute Aplastic Crisis", "Streptococcus pyogenes; leading to acute rheumatic fever", "Coxsackievirus A16; causing severe viral meningitis"]'::jsonb, 2, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Rubella (German Measles)", "Erythema Infectiosum (Fifth Disease)", "Rubeola (Measles)", "Roseola Infantum (Exanthem Subitum)", "Scarlet Fever"]'::jsonb, 3, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours", "Ketoconazole 2% cream; applied to the trunk and limbs for 3 days", "Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime"]'::jsonb, 2, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["High-dose intravenous antibiotics and surgical debridement of the scales", "Topical Permethrin 5% cream alone applied once", "Strict isolation and daily washing with soap and water", "Oral Griseofulvin for 12 weeks", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream"]'::jsonb, 4, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Sarcoptes scabiei", "Strongyloides stercoralis", "Ancylostoma braziliense (animal hookworm)", "Leishmania tropica", "Dracunculus medinensis"]'::jsonb, 2, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse", "A secondary deep fungal infection within the pubic follicles", "A congenital vascular anomaly flared by the infestation", "Deep dermal deposition of blue melanin pigment by activated melanocytes", "Localized vascular thrombosis in the superficial capillaries caused by scratching"]'::jsonb, 0, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Inhalation of dry bird droppings", "Barefoot contact with beach sand", "Contact with contaminated sheep or goats", "Bite of an infected Ixodes Tick", "Bite of an infected Phlebotomine Sandfly"]'::jsonb, 4, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Cimex lectularius (Bedbugs)", "Ancylostoma braziliense (Hookworm)", "Pthirus pubis (Pubic lice)", "Ixodes scapularis (Ticks)", "Sarcoptes scabiei (Scabies)"]'::jsonb, 0, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 25-year-old woman who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Erysipeloid", "Blastomycosis", "Sporotrichosis", "Cutaneous Leishmaniasis"]'::jsonb, 0, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 35-year-old woman is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Intravenous Ampicillin", "Oral Cephalexin", "Topical Ketoconazole cream", "Topical Mupirocin ointment", "Oral Vancomycin"]'::jsonb, 3, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 55-year-old male is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Post-streptococcal Glomerulonephritis (PSGN)", "Streptococcal toxic shock syndrome", "Scarlet Fever", "Acute Rheumatic Fever (ARF)", "Acute glomerulonephritis and carditis"]'::jsonb, 0, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 17-year-old man toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["BP180 (Type XVII Collagen)", "Desmocollin 1", "Type VII Collagen", "Desmoglein 3", "Desmoglein 1"]'::jsonb, 4, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless girl presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Non-bullous Impetigo", "Ecthyma", "Necrotizing Fasciitis", "Erysipelas", "Pyoderma Gangrenosum"]'::jsonb, 1, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 78-year-old man presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Bartonella henselae", "Staphylococcus aureus", "Streptococcus pyogenes (Group A Strep)", "Mycobacterium marinum", "Pseudomonas aeruginosa"]'::jsonb, 2, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 25-year-old boy with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The rapid, hyperacute spread within hours", "The presence of high fever and leukocytosis", "Successful treatment with penicillin instead of cephalexin", "The presence of prominent lymphatic streaking"]'::jsonb, 0, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 45-year-old male presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin", "Obtain double-volume blood cultures and wait for the results", "Emergent surgical consultation for exploratory debridement", "Order an urgent MRI of the left lower extremity with contrast", "Apply high-potency topical steroids to reduce local inflammation"]'::jsonb, 2, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 68-year-old man complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Candida albicans", "Malassezia furfur", "Corynebacterium minutissimum", "Trichophyton rubrum", "Staphylococcus aureus"]'::jsonb, 2, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 38-year-old female athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Mechanical erosion from repetitive friction and hyperhidrosis", "Bacterial production of extracellular proteases that digest the stratum corneum", "Superficial invasion of dermatophytes into the sweat glands", "A chronic contact allergy to rubber compounds in athletic shoes", "Autoimmune-mediated destruction of plantar sweat ducts"]'::jsonb, 1, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 28-year-old man develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is highly contagious and spreads to family members through air droplets", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia", "It is caused by a type IV hypersensitivity reaction to chlorine", "It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It leads to chronic, scarred alopecia of the affected hair follicles"]'::jsonb, 3, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 25-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Topical Permethrin 5% cream", "Oral Valacyclovir", "Intravenous Ganciclovir", "Ciprofloxacin or Doxycycline", "Oral Griseofulvin"]'::jsonb, 3, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Microsporum canis", "Candida albicans", "Malassezia furfur", "Trichophyton rubrum", "Trichophyton tonsurans"]'::jsonb, 4, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Clobetasol propionate ointment", "Oral Griseofulvin or oral Terbinafine", "Oral Amoxicillin-Clavulanate", "Topical Terbinafine 1% cream", "Topical Ketoconazole 2% shampoo daily"]'::jsonb, 1, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["A neoplastic proliferation of follicular dendritic cells", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "Direct fungal invasion into the meninges and skull bone", "A congenital vascular malformation triggered by inflammation"]'::jsonb, 2, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 55-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Malassezia furfur", "Trichophyton tonsurans", "Microsporum canis", "Trichophyton rubrum", "Candida albicans"]'::jsonb, 3, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Tinea cruris presents with satellite pustules, whereas Candidiasis does not", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Tinea cruris is never itchy, while Candidiasis is extremely painful", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast", "Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum"]'::jsonb, 4, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 45-year-old woman presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The fingernails of the non-dominant hand", "The axillae for coral-red fluorescence", "The palms of the hands (typically only one palm is affected)", "The oral cavity for white plaques", "The scalp for black dot alopecia"]'::jsonb, 2, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 72-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Majocchi''s Granuloma", "Sporotrichosis", "Kerion", "Erythema Nodosum", "Cellulitis"]'::jsonb, 0, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old female presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "1 week of oral Terbinafine; no monitoring is required", "6 weeks of oral Terbinafine; no laboratory monitoring is required", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored", "12 months of oral Terbinafine; CBC must be monitored weekly"]'::jsonb, 3, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young girl returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Lactic acid", "Azelaic acid", "Coproporphyrin III", "Uric acid", "Melanin"]'::jsonb, 1, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Gram-positive rods in chains", "Spherules containing endospores", "Pseudohyphae and budding yeast cells", "Branching, septate hyphae", "Henderson-Paterson bodies"]'::jsonb, 2, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Herpes Simplex Virus; oral Acyclovir", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals", "Trichophyton rubrum; oral Terbinafine for 12 weeks", "Pseudomonas aeruginosa; soak in diluted bleach daily", "Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin"]'::jsonb, 1, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 38-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Leishmaniasis", "Sporotrichosis", "Cutaneous Anthrax", "Majocchi''s Granuloma", "Blastomycosis"]'::jsonb, 1, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old female recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Coccidioidomycosis", "Histoplasmosis", "Blastomycosis", "Sporotrichosis", "Tinea Versicolor"]'::jsonb, 0, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 12-year-old woman from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Blastomyces dermatitidis", "Coccidioides immitis", "Candida albicans", "Sporothrix schenckii", "Histoplasma capsulatum"]'::jsonb, 0, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Soil contaminated with bird or bat droppings (caves, chicken coops)", "Public swimming pools and fish tanks", "Decaying wood and organic matter near rivers", "Infected sheep and livestock", "Arid desert sand of the Southwest US"]'::jsonb, 0, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 55-year-old woman presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Eczema Herpeticum (Kaposi varicelliform eruption)", "Bullous Impetigo", "Toxic Epidermal Necrolysis (TEN)", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Disseminated Molluscum Contagiosum"]'::jsonb, 0, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 28-year-old female presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Dorsal root ganglion (Sensory nerve ganglion)", "Trigeminal ganglion", "Keratinocytes of the basal epidermis", "Langerhans cells in the dermis", "Splenic macrophages"]'::jsonb, 0, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old man presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Koebner sign; it indicates the shingles was triggered by local scratching", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss", "Nikolsky sign; it indicates severe epidermal detachment and SJS", "Henderson sign; it indicates a poxvirus superinfection", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement"]'::jsonb, 4, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Bell''s palsy with secondary ear infection", "Meniere''s disease with HSV-1 outbreak", "Nicolau Syndrome", "Gorlin Syndrome"]'::jsonb, 0, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Multinucleated giant cells with ballooning degeneration of the epidermis", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes", "Massive pseudoepitheliomatous hyperplasia with microabscesses", "A dense septal panniculitis without vasculitis", "Acantholysis with a ''fishnet'' immunofluorescence pattern"]'::jsonb, 1, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Thrombosed, clotted capillaries supplying the rapidly growing wart tissue", "Necrotic nuclei of basal cells killed by the HPV virus", "Viral spores embedded in the stratum corneum", "Trap-door collection of dirt and environmental debris", "Sites of focal melanin deposition within the basal layer"]'::jsonb, 0, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Herpes Simplex Virus", "Orf virus (a parapoxvirus)", "Coxsackievirus A16", "Bacillus anthracis", "Human Papillomavirus"]'::jsonb, 1, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "Parvovirus B19; aplastic crisis in healthy children", "HHV-6; febrile seizures leading to epilepsy", "Herpes Simplex Virus 1; permanent scarring alopecia", "Sarcoptes scabiei; post-infectious glomerulonephritis"]'::jsonb, 0, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["HHV-6; inducing status epilepticus", "Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "Coxsackievirus A16; causing severe viral meningitis", "Streptococcus pyogenes; leading to acute rheumatic fever", "Parvovirus B19; precipitating an acute Aplastic Crisis"]'::jsonb, 4, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Rubeola (Measles)", "Roseola Infantum (Exanthem Subitum)", "Rubella (German Measles)", "Scarlet Fever", "Erythema Infectiosum (Fifth Disease)"]'::jsonb, 1, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Ketoconazole 2% cream; applied to the trunk and limbs for 3 days", "Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours", "Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes"]'::jsonb, 2, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream", "High-dose intravenous antibiotics and surgical debridement of the scales", "Strict isolation and daily washing with soap and water", "Topical Permethrin 5% cream alone applied once", "Oral Griseofulvin for 12 weeks"]'::jsonb, 0, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Ancylostoma braziliense (animal hookworm)", "Dracunculus medinensis", "Sarcoptes scabiei", "Leishmania tropica", "Strongyloides stercoralis"]'::jsonb, 0, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["A congenital vascular anomaly flared by the infestation", "A secondary deep fungal infection within the pubic follicles", "Deep dermal deposition of blue melanin pigment by activated melanocytes", "Localized vascular thrombosis in the superficial capillaries caused by scratching", "A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse"]'::jsonb, 4, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Bite of an infected Phlebotomine Sandfly", "Barefoot contact with beach sand", "Bite of an infected Ixodes Tick", "Inhalation of dry bird droppings", "Contact with contaminated sheep or goats"]'::jsonb, 0, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A 28-year-old man who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Erysipeloid", "Sporotrichosis", "Blastomycosis", "Cutaneous Leishmaniasis", "Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)"]'::jsonb, 4, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 19-year-old male is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Ketoconazole cream", "Oral Cephalexin", "Intravenous Ampicillin", "Topical Mupirocin ointment", "Oral Vancomycin"]'::jsonb, 3, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 50-year-old man is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Streptococcal toxic shock syndrome", "Post-streptococcal Glomerulonephritis (PSGN)", "Scarlet Fever", "Acute glomerulonephritis and carditis", "Acute Rheumatic Fever (ARF)"]'::jsonb, 1, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 55-year-old boy toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["Desmoglein 3", "BP180 (Type XVII Collagen)", "Type VII Collagen", "Desmocollin 1", "Desmoglein 1"]'::jsonb, 4, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless boy presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Erysipelas", "Pyoderma Gangrenosum", "Ecthyma", "Non-bullous Impetigo", "Necrotizing Fasciitis"]'::jsonb, 2, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 22-year-old female presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Mycobacterium marinum", "Streptococcus pyogenes (Group A Strep)", "Pseudomonas aeruginosa", "Bartonella henselae", "Staphylococcus aureus"]'::jsonb, 1, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 55-year-old female with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["The presence of prominent lymphatic streaking", "The rapid, hyperacute spread within hours", "Successful treatment with penicillin instead of cephalexin", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The presence of high fever and leukocytosis"]'::jsonb, 3, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 35-year-old boy presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Order an urgent MRI of the left lower extremity with contrast", "Apply high-potency topical steroids to reduce local inflammation", "Emergent surgical consultation for exploratory debridement", "Obtain double-volume blood cultures and wait for the results", "Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin"]'::jsonb, 2, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 55-year-old female complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Malassezia furfur", "Staphylococcus aureus", "Corynebacterium minutissimum", "Trichophyton rubrum", "Candida albicans"]'::jsonb, 2, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 62-year-old female athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Autoimmune-mediated destruction of plantar sweat ducts", "Superficial invasion of dermatophytes into the sweat glands", "Mechanical erosion from repetitive friction and hyperhidrosis", "A chronic contact allergy to rubber compounds in athletic shoes", "Bacterial production of extracellular proteases that digest the stratum corneum"]'::jsonb, 4, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 19-year-old woman develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is highly contagious and spreads to family members through air droplets", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia", "It is caused by a type IV hypersensitivity reaction to chlorine", "It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It leads to chronic, scarred alopecia of the affected hair follicles"]'::jsonb, 3, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 22-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Ciprofloxacin or Doxycycline", "Topical Permethrin 5% cream", "Intravenous Ganciclovir", "Oral Griseofulvin", "Oral Valacyclovir"]'::jsonb, 0, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Malassezia furfur", "Microsporum canis", "Trichophyton rubrum", "Trichophyton tonsurans", "Candida albicans"]'::jsonb, 3, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Clobetasol propionate ointment", "Topical Terbinafine 1% cream", "Oral Amoxicillin-Clavulanate", "Oral Griseofulvin or oral Terbinafine", "Topical Ketoconazole 2% shampoo daily"]'::jsonb, 3, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["A congenital vascular malformation triggered by inflammation", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)", "Direct fungal invasion into the meninges and skull bone", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "A neoplastic proliferation of follicular dendritic cells"]'::jsonb, 3, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 68-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Trichophyton rubrum", "Microsporum canis", "Trichophyton tonsurans", "Candida albicans", "Malassezia furfur"]'::jsonb, 0, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum", "Tinea cruris presents with satellite pustules, whereas Candidiasis does not", "Tinea cruris is never itchy, while Candidiasis is extremely painful", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast"]'::jsonb, 1, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 72-year-old female presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The axillae for coral-red fluorescence", "The fingernails of the non-dominant hand", "The oral cavity for white plaques", "The scalp for black dot alopecia", "The palms of the hands (typically only one palm is affected)"]'::jsonb, 4, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 45-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Majocchi''s Granuloma", "Kerion", "Cellulitis", "Erythema Nodosum", "Sporotrichosis"]'::jsonb, 0, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old female presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["6 weeks of oral Terbinafine; no laboratory monitoring is required", "12 months of oral Terbinafine; CBC must be monitored weekly", "1 week of oral Terbinafine; no monitoring is required", "12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored"]'::jsonb, 4, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young woman returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Coproporphyrin III", "Azelaic acid", "Lactic acid", "Uric acid", "Melanin"]'::jsonb, 1, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Branching, septate hyphae", "Spherules containing endospores", "Henderson-Paterson bodies", "Gram-positive rods in chains", "Pseudohyphae and budding yeast cells"]'::jsonb, 4, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Pseudomonas aeruginosa; soak in diluted bleach daily", "Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin", "Trichophyton rubrum; oral Terbinafine for 12 weeks", "Herpes Simplex Virus; oral Acyclovir", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals"]'::jsonb, 4, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 38-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Blastomycosis", "Cutaneous Anthrax", "Majocchi''s Granuloma", "Leishmaniasis", "Sporotrichosis"]'::jsonb, 4, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old female recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Sporotrichosis", "Coccidioidomycosis", "Histoplasmosis", "Tinea Versicolor", "Blastomycosis"]'::jsonb, 1, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 25-year-old woman from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Coccidioides immitis", "Sporothrix schenckii", "Blastomyces dermatitidis", "Candida albicans", "Histoplasma capsulatum"]'::jsonb, 2, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Public swimming pools and fish tanks", "Infected sheep and livestock", "Arid desert sand of the Southwest US", "Decaying wood and organic matter near rivers", "Soil contaminated with bird or bat droppings (caves, chicken coops)"]'::jsonb, 4, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 68-year-old male presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Eczema Herpeticum (Kaposi varicelliform eruption)", "Disseminated Molluscum Contagiosum", "Bullous Impetigo", "Toxic Epidermal Necrolysis (TEN)", "Acute Generalized Exanthematous Pustulosis (AGEP)"]'::jsonb, 0, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 45-year-old boy presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Splenic macrophages", "Trigeminal ganglion", "Dorsal root ganglion (Sensory nerve ganglion)", "Keratinocytes of the basal epidermis", "Langerhans cells in the dermis"]'::jsonb, 2, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old boy presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss", "Henderson sign; it indicates a poxvirus superinfection", "Koebner sign; it indicates the shingles was triggered by local scratching", "Nikolsky sign; it indicates severe epidermal detachment and SJS"]'::jsonb, 0, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Bell''s palsy with secondary ear infection", "Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Meniere''s disease with HSV-1 outbreak", "Gorlin Syndrome", "Nicolau Syndrome"]'::jsonb, 1, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Massive pseudoepitheliomatous hyperplasia with microabscesses", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes", "Multinucleated giant cells with ballooning degeneration of the epidermis", "Acantholysis with a ''fishnet'' immunofluorescence pattern", "A dense septal panniculitis without vasculitis"]'::jsonb, 1, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Sites of focal melanin deposition within the basal layer", "Trap-door collection of dirt and environmental debris", "Viral spores embedded in the stratum corneum", "Necrotic nuclei of basal cells killed by the HPV virus", "Thrombosed, clotted capillaries supplying the rapidly growing wart tissue"]'::jsonb, 4, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure", "There is no reliable clinical difference; a biopsy is always required", "Warts are soft and fluctuant, whereas calluses are rock-hard", "Calluses show pinpoint bleeding upon paring and are only painful with direct pressure", "Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not"]'::jsonb, 0, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Bacillus anthracis", "Orf virus (a parapoxvirus)", "Coxsackievirus A16", "Herpes Simplex Virus", "Human Papillomavirus"]'::jsonb, 1, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Sarcoptes scabiei; post-infectious glomerulonephritis", "Parvovirus B19; aplastic crisis in healthy children", "HHV-6; febrile seizures leading to epilepsy", "Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "Herpes Simplex Virus 1; permanent scarring alopecia"]'::jsonb, 3, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["Parvovirus B19; precipitating an acute Aplastic Crisis", "Streptococcus pyogenes; leading to acute rheumatic fever", "HHV-6; inducing status epilepticus", "Coxsackievirus A16; causing severe viral meningitis", "Measles virus; leading to subacute sclerosing panencephalitis (SSPE)"]'::jsonb, 0, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Scarlet Fever", "Rubeola (Measles)", "Roseola Infantum (Exanthem Subitum)", "Erythema Infectiosum (Fifth Disease)", "Rubella (German Measles)"]'::jsonb, 2, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes", "Ketoconazole 2% cream; applied to the trunk and limbs for 3 days"]'::jsonb, 2, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Topical Permethrin 5% cream alone applied once", "Strict isolation and daily washing with soap and water", "High-dose intravenous antibiotics and surgical debridement of the scales", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream", "Oral Griseofulvin for 12 weeks"]'::jsonb, 3, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Dracunculus medinensis", "Sarcoptes scabiei", "Ancylostoma braziliense (animal hookworm)", "Strongyloides stercoralis", "Leishmania tropica"]'::jsonb, 2, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Contact with contaminated sheep or goats", "Inhalation of dry bird droppings", "Bite of an infected Ixodes Tick", "Barefoot contact with beach sand", "Bite of an infected Phlebotomine Sandfly"]'::jsonb, 4, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Sarcoptes scabiei (Scabies)", "Pthirus pubis (Pubic lice)", "Cimex lectularius (Bedbugs)", "Ixodes scapularis (Ticks)", "Ancylostoma braziliense (Hookworm)"]'::jsonb, 2, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 25-year-old boy who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Sporotrichosis", "Cutaneous Leishmaniasis", "Blastomycosis", "Erysipeloid"]'::jsonb, 0, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 17-year-old female is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Oral Cephalexin", "Topical Ketoconazole cream", "Intravenous Ampicillin", "Topical Mupirocin ointment", "Oral Vancomycin"]'::jsonb, 3, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 45-year-old female is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Post-streptococcal Glomerulonephritis (PSGN)", "Streptococcal toxic shock syndrome", "Acute Rheumatic Fever (ARF)", "Scarlet Fever", "Acute glomerulonephritis and carditis"]'::jsonb, 0, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 62-year-old girl toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["BP180 (Type XVII Collagen)", "Desmoglein 1", "Desmoglein 3", "Desmocollin 1", "Type VII Collagen"]'::jsonb, 1, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless girl presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Pyoderma Gangrenosum", "Necrotizing Fasciitis", "Erysipelas", "Ecthyma", "Non-bullous Impetigo"]'::jsonb, 3, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 22-year-old boy presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Pseudomonas aeruginosa", "Bartonella henselae", "Streptococcus pyogenes (Group A Strep)", "Staphylococcus aureus", "Mycobacterium marinum"]'::jsonb, 2, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 35-year-old boy with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["Successful treatment with penicillin instead of cephalexin", "The presence of prominent lymphatic streaking", "The rapid, hyperacute spread within hours", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The presence of high fever and leukocytosis"]'::jsonb, 3, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 17-year-old man presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Obtain double-volume blood cultures and wait for the results", "Emergent surgical consultation for exploratory debridement", "Order an urgent MRI of the left lower extremity with contrast", "Apply high-potency topical steroids to reduce local inflammation", "Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin"]'::jsonb, 1, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 22-year-old man complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Staphylococcus aureus", "Corynebacterium minutissimum", "Malassezia furfur", "Trichophyton rubrum", "Candida albicans"]'::jsonb, 1, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 55-year-old female athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Superficial invasion of dermatophytes into the sweat glands", "Mechanical erosion from repetitive friction and hyperhidrosis", "Bacterial production of extracellular proteases that digest the stratum corneum", "A chronic contact allergy to rubber compounds in athletic shoes", "Autoimmune-mediated destruction of plantar sweat ducts"]'::jsonb, 2, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 62-year-old man develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It is highly contagious and spreads to family members through air droplets", "It leads to chronic, scarred alopecia of the affected hair follicles", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia", "It is caused by a type IV hypersensitivity reaction to chlorine"]'::jsonb, 0, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 12-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Oral Valacyclovir", "Ciprofloxacin or Doxycycline", "Intravenous Ganciclovir", "Topical Permethrin 5% cream", "Oral Griseofulvin"]'::jsonb, 1, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Trichophyton tonsurans", "Trichophyton rubrum", "Candida albicans", "Malassezia furfur", "Microsporum canis"]'::jsonb, 0, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["Direct fungal invasion into the meninges and skull bone", "A congenital vascular malformation triggered by inflammation", "A neoplastic proliferation of follicular dendritic cells", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte"]'::jsonb, 4, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 72-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Trichophyton rubrum", "Microsporum canis", "Candida albicans", "Malassezia furfur", "Trichophyton tonsurans"]'::jsonb, 0, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Tinea cruris is never itchy, while Candidiasis is extremely painful", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum", "Tinea cruris presents with satellite pustules, whereas Candidiasis does not"]'::jsonb, 3, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 22-year-old girl presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The axillae for coral-red fluorescence", "The fingernails of the non-dominant hand", "The scalp for black dot alopecia", "The palms of the hands (typically only one palm is affected)", "The oral cavity for white plaques"]'::jsonb, 3, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 38-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Erythema Nodosum", "Kerion", "Cellulitis", "Majocchi''s Granuloma", "Sporotrichosis"]'::jsonb, 3, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old girl presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["12 months of oral Terbinafine; CBC must be monitored weekly", "12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "6 weeks of oral Terbinafine; no laboratory monitoring is required", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored", "1 week of oral Terbinafine; no monitoring is required"]'::jsonb, 3, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young girl returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Uric acid", "Azelaic acid", "Coproporphyrin III", "Melanin", "Lactic acid"]'::jsonb, 1, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Henderson-Paterson bodies", "Pseudohyphae and budding yeast cells", "Branching, septate hyphae", "Gram-positive rods in chains", "Spherules containing endospores"]'::jsonb, 1, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin", "Pseudomonas aeruginosa; soak in diluted bleach daily", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals", "Herpes Simplex Virus; oral Acyclovir", "Trichophyton rubrum; oral Terbinafine for 12 weeks"]'::jsonb, 2, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 55-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Blastomycosis", "Majocchi''s Granuloma", "Leishmaniasis", "Cutaneous Anthrax", "Sporotrichosis"]'::jsonb, 4, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old girl recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Coccidioidomycosis", "Blastomycosis", "Sporotrichosis", "Histoplasmosis", "Tinea Versicolor"]'::jsonb, 0, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 72-year-old woman from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Sporothrix schenckii", "Coccidioides immitis", "Histoplasma capsulatum", "Blastomyces dermatitidis", "Candida albicans"]'::jsonb, 3, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Decaying wood and organic matter near rivers", "Infected sheep and livestock", "Public swimming pools and fish tanks", "Arid desert sand of the Southwest US", "Soil contaminated with bird or bat droppings (caves, chicken coops)"]'::jsonb, 4, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 17-year-old man presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Toxic Epidermal Necrolysis (TEN)", "Disseminated Molluscum Contagiosum", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Bullous Impetigo", "Eczema Herpeticum (Kaposi varicelliform eruption)"]'::jsonb, 4, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 19-year-old man presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Dorsal root ganglion (Sensory nerve ganglion)", "Langerhans cells in the dermis", "Splenic macrophages", "Trigeminal ganglion", "Keratinocytes of the basal epidermis"]'::jsonb, 0, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old girl presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Nikolsky sign; it indicates severe epidermal detachment and SJS", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss", "Henderson sign; it indicates a poxvirus superinfection", "Koebner sign; it indicates the shingles was triggered by local scratching"]'::jsonb, 1, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Meniere''s disease with HSV-1 outbreak", "Gorlin Syndrome", "Bell''s palsy with secondary ear infection", "Nicolau Syndrome", "Ramsay Hunt Syndrome (Herpes Zoster Oticus)"]'::jsonb, 4, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Multinucleated giant cells with ballooning degeneration of the epidermis", "A dense septal panniculitis without vasculitis", "Acantholysis with a ''fishnet'' immunofluorescence pattern", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes", "Massive pseudoepitheliomatous hyperplasia with microabscesses"]'::jsonb, 3, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Thrombosed, clotted capillaries supplying the rapidly growing wart tissue", "Viral spores embedded in the stratum corneum", "Sites of focal melanin deposition within the basal layer", "Necrotic nuclei of basal cells killed by the HPV virus", "Trap-door collection of dirt and environmental debris"]'::jsonb, 0, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure", "Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not", "Warts are soft and fluctuant, whereas calluses are rock-hard", "There is no reliable clinical difference; a biopsy is always required", "Calluses show pinpoint bleeding upon paring and are only painful with direct pressure"]'::jsonb, 0, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Herpes Simplex Virus", "Human Papillomavirus", "Orf virus (a parapoxvirus)", "Coxsackievirus A16", "Bacillus anthracis"]'::jsonb, 2, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "HHV-6; febrile seizures leading to epilepsy", "Sarcoptes scabiei; post-infectious glomerulonephritis", "Parvovirus B19; aplastic crisis in healthy children", "Herpes Simplex Virus 1; permanent scarring alopecia"]'::jsonb, 0, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "Streptococcus pyogenes; leading to acute rheumatic fever", "Parvovirus B19; precipitating an acute Aplastic Crisis", "Coxsackievirus A16; causing severe viral meningitis", "HHV-6; inducing status epilepticus"]'::jsonb, 2, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Rubeola (Measles)", "Scarlet Fever", "Roseola Infantum (Exanthem Subitum)", "Rubella (German Measles)", "Erythema Infectiosum (Fifth Disease)"]'::jsonb, 2, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime", "Ketoconazole 2% cream; applied to the trunk and limbs for 3 days", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours"]'::jsonb, 4, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Topical Permethrin 5% cream alone applied once", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream", "High-dose intravenous antibiotics and surgical debridement of the scales", "Strict isolation and daily washing with soap and water", "Oral Griseofulvin for 12 weeks"]'::jsonb, 1, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Leishmania tropica", "Dracunculus medinensis", "Sarcoptes scabiei", "Strongyloides stercoralis", "Ancylostoma braziliense (animal hookworm)"]'::jsonb, 4, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse", "Deep dermal deposition of blue melanin pigment by activated melanocytes", "Localized vascular thrombosis in the superficial capillaries caused by scratching", "A secondary deep fungal infection within the pubic follicles", "A congenital vascular anomaly flared by the infestation"]'::jsonb, 0, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Bite of an infected Phlebotomine Sandfly", "Bite of an infected Ixodes Tick", "Barefoot contact with beach sand", "Contact with contaminated sheep or goats", "Inhalation of dry bird droppings"]'::jsonb, 0, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Sarcoptes scabiei (Scabies)", "Pthirus pubis (Pubic lice)", "Ixodes scapularis (Ticks)", "Cimex lectularius (Bedbugs)", "Ancylostoma braziliense (Hookworm)"]'::jsonb, 3, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 55-year-old female who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Blastomycosis", "Sporotrichosis", "Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Erysipeloid", "Cutaneous Leishmaniasis"]'::jsonb, 2, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 78-year-old man is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Intravenous Ampicillin", "Topical Mupirocin ointment", "Oral Vancomycin", "Oral Cephalexin", "Topical Ketoconazole cream"]'::jsonb, 1, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 78-year-old man is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Scarlet Fever", "Acute Rheumatic Fever (ARF)", "Post-streptococcal Glomerulonephritis (PSGN)", "Streptococcal toxic shock syndrome", "Acute glomerulonephritis and carditis"]'::jsonb, 2, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 78-year-old girl toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["Desmoglein 3", "BP180 (Type XVII Collagen)", "Type VII Collagen", "Desmoglein 1", "Desmocollin 1"]'::jsonb, 3, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless boy presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Necrotizing Fasciitis", "Pyoderma Gangrenosum", "Non-bullous Impetigo", "Erysipelas", "Ecthyma"]'::jsonb, 4, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 62-year-old girl presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Bartonella henselae", "Pseudomonas aeruginosa", "Staphylococcus aureus", "Streptococcus pyogenes (Group A Strep)", "Mycobacterium marinum"]'::jsonb, 3, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 62-year-old boy with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["The rapid, hyperacute spread within hours", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The presence of high fever and leukocytosis", "The presence of prominent lymphatic streaking", "Successful treatment with penicillin instead of cephalexin"]'::jsonb, 1, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 72-year-old man presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Emergent surgical consultation for exploratory debridement", "Order an urgent MRI of the left lower extremity with contrast", "Apply high-potency topical steroids to reduce local inflammation", "Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin", "Obtain double-volume blood cultures and wait for the results"]'::jsonb, 0, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 72-year-old boy complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Candida albicans", "Malassezia furfur", "Trichophyton rubrum", "Corynebacterium minutissimum", "Staphylococcus aureus"]'::jsonb, 3, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 72-year-old woman athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Superficial invasion of dermatophytes into the sweat glands", "Mechanical erosion from repetitive friction and hyperhidrosis", "Bacterial production of extracellular proteases that digest the stratum corneum", "A chronic contact allergy to rubber compounds in athletic shoes", "Autoimmune-mediated destruction of plantar sweat ducts"]'::jsonb, 2, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 72-year-old boy develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is highly contagious and spreads to family members through air droplets", "It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It is caused by a type IV hypersensitivity reaction to chlorine", "It leads to chronic, scarred alopecia of the affected hair follicles", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia"]'::jsonb, 1, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 25-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Oral Valacyclovir", "Topical Permethrin 5% cream", "Ciprofloxacin or Doxycycline", "Oral Griseofulvin", "Intravenous Ganciclovir"]'::jsonb, 2, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Microsporum canis", "Candida albicans", "Trichophyton rubrum", "Malassezia furfur", "Trichophyton tonsurans"]'::jsonb, 4, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Oral Amoxicillin-Clavulanate", "Oral Griseofulvin or oral Terbinafine", "Topical Terbinafine 1% cream", "Topical Clobetasol propionate ointment", "Topical Ketoconazole 2% shampoo daily"]'::jsonb, 1, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["Direct fungal invasion into the meninges and skull bone", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "A congenital vascular malformation triggered by inflammation", "A neoplastic proliferation of follicular dendritic cells", "A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)"]'::jsonb, 1, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 78-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Trichophyton tonsurans", "Malassezia furfur", "Microsporum canis", "Trichophyton rubrum", "Candida albicans"]'::jsonb, 3, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Tinea cruris presents with satellite pustules, whereas Candidiasis does not", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast", "Tinea cruris is never itchy, while Candidiasis is extremely painful"]'::jsonb, 0, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 35-year-old woman presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The palms of the hands (typically only one palm is affected)", "The scalp for black dot alopecia", "The axillae for coral-red fluorescence", "The oral cavity for white plaques", "The fingernails of the non-dominant hand"]'::jsonb, 0, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 35-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Cellulitis", "Sporotrichosis", "Erythema Nodosum", "Kerion", "Majocchi''s Granuloma"]'::jsonb, 4, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old woman presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["6 weeks of oral Terbinafine; no laboratory monitoring is required", "12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "1 week of oral Terbinafine; no monitoring is required", "12 months of oral Terbinafine; CBC must be monitored weekly", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored"]'::jsonb, 4, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young boy returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Uric acid", "Azelaic acid", "Melanin", "Lactic acid", "Coproporphyrin III"]'::jsonb, 1, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Pseudohyphae and budding yeast cells", "Henderson-Paterson bodies", "Branching, septate hyphae", "Spherules containing endospores", "Gram-positive rods in chains"]'::jsonb, 0, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Herpes Simplex Virus; oral Acyclovir", "Trichophyton rubrum; oral Terbinafine for 12 weeks", "Pseudomonas aeruginosa; soak in diluted bleach daily", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals", "Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin"]'::jsonb, 3, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 19-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Leishmaniasis", "Sporotrichosis", "Majocchi''s Granuloma", "Cutaneous Anthrax", "Blastomycosis"]'::jsonb, 1, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old male recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Histoplasmosis", "Sporotrichosis", "Blastomycosis", "Tinea Versicolor", "Coccidioidomycosis"]'::jsonb, 4, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 22-year-old boy from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Sporothrix schenckii", "Blastomyces dermatitidis", "Candida albicans", "Coccidioides immitis", "Histoplasma capsulatum"]'::jsonb, 1, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Soil contaminated with bird or bat droppings (caves, chicken coops)", "Infected sheep and livestock", "Public swimming pools and fish tanks", "Decaying wood and organic matter near rivers", "Arid desert sand of the Southwest US"]'::jsonb, 0, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 45-year-old male presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Toxic Epidermal Necrolysis (TEN)", "Disseminated Molluscum Contagiosum", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Eczema Herpeticum (Kaposi varicelliform eruption)", "Bullous Impetigo"]'::jsonb, 3, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 45-year-old girl presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Splenic macrophages", "Langerhans cells in the dermis", "Dorsal root ganglion (Sensory nerve ganglion)", "Trigeminal ganglion", "Keratinocytes of the basal epidermis"]'::jsonb, 2, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old boy presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss", "Henderson sign; it indicates a poxvirus superinfection", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement", "Nikolsky sign; it indicates severe epidermal detachment and SJS", "Koebner sign; it indicates the shingles was triggered by local scratching"]'::jsonb, 2, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Bell''s palsy with secondary ear infection", "Meniere''s disease with HSV-1 outbreak", "Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Gorlin Syndrome", "Nicolau Syndrome"]'::jsonb, 2, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Multinucleated giant cells with ballooning degeneration of the epidermis", "Massive pseudoepitheliomatous hyperplasia with microabscesses", "A dense septal panniculitis without vasculitis", "Acantholysis with a ''fishnet'' immunofluorescence pattern", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes"]'::jsonb, 4, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Viral spores embedded in the stratum corneum", "Necrotic nuclei of basal cells killed by the HPV virus", "Thrombosed, clotted capillaries supplying the rapidly growing wart tissue", "Trap-door collection of dirt and environmental debris", "Sites of focal melanin deposition within the basal layer"]'::jsonb, 2, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not", "Warts are soft and fluctuant, whereas calluses are rock-hard", "Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure", "Calluses show pinpoint bleeding upon paring and are only painful with direct pressure", "There is no reliable clinical difference; a biopsy is always required"]'::jsonb, 2, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Human Papillomavirus", "Herpes Simplex Virus", "Coxsackievirus A16", "Orf virus (a parapoxvirus)", "Bacillus anthracis"]'::jsonb, 3, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "HHV-6; febrile seizures leading to epilepsy", "Sarcoptes scabiei; post-infectious glomerulonephritis", "Herpes Simplex Virus 1; permanent scarring alopecia", "Parvovirus B19; aplastic crisis in healthy children"]'::jsonb, 0, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["HHV-6; inducing status epilepticus", "Coxsackievirus A16; causing severe viral meningitis", "Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "Streptococcus pyogenes; leading to acute rheumatic fever", "Parvovirus B19; precipitating an acute Aplastic Crisis"]'::jsonb, 4, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Scarlet Fever", "Erythema Infectiosum (Fifth Disease)", "Rubella (German Measles)", "Rubeola (Measles)", "Roseola Infantum (Exanthem Subitum)"]'::jsonb, 4, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'A 24-year-old student presents with intense, progressive itching that is worst at night. His roommate is also complaining of similar itching. Physical exam shows small, erythematous papules, excoriations, and a few thin, linear burrows in the finger webs, wrists, and periumbilical area. What is the first-line topical treatment for this condition, and how should it be applied?', '["Clobetasol propionate 0.05% cream; applied to itchy areas daily at bedtime", "Mupirocin 2% ointment; applied strictly to the visible linear burrows twice daily", "Ketoconazole 2% cream; applied to the trunk and limbs for 3 days", "Permethrin 1% shampoo; massaged into the scalp and washed off after 10 minutes", "Permethrin 5% cream; applied head-to-toe (including under fingernails/toes) and washed off after 8-14 hours"]'::jsonb, 4, 'This is a classic presentation of Scabies, caused by the Sarcoptes scabiei mite. It is transmitted by close skin-to-skin contact. The first-line topical treatment is Permethrin 5% cream, which must be applied thoroughly from the neck down (including web spaces, under nails, umbilicus, and soles of feet) and left on for 8-14 hours before washing off. Treatment must be repeated in 1 week, and all close contacts must be treated simultaneously.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Oral Griseofulvin for 12 weeks", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream", "Strict isolation and daily washing with soap and water", "Topical Permethrin 5% cream alone applied once", "High-dose intravenous antibiotics and surgical debridement of the scales"]'::jsonb, 1, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Strongyloides stercoralis", "Leishmania tropica", "Sarcoptes scabiei", "Dracunculus medinensis", "Ancylostoma braziliense (animal hookworm)"]'::jsonb, 4, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["Localized vascular thrombosis in the superficial capillaries caused by scratching", "A secondary deep fungal infection within the pubic follicles", "A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse", "A congenital vascular anomaly flared by the infestation", "Deep dermal deposition of blue melanin pigment by activated melanocytes"]'::jsonb, 2, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Bite of an infected Ixodes Tick", "Inhalation of dry bird droppings", "Barefoot contact with beach sand", "Bite of an infected Phlebotomine Sandfly", "Contact with contaminated sheep or goats"]'::jsonb, 3, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Sarcoptes scabiei (Scabies)", "Ancylostoma braziliense (Hookworm)", "Ixodes scapularis (Ticks)", "Cimex lectularius (Bedbugs)", "Pthirus pubis (Pubic lice)"]'::jsonb, 3, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 55-year-old female who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Erysipeloid", "Blastomycosis", "Cutaneous Leishmaniasis", "Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Sporotrichosis"]'::jsonb, 3, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 19-year-old male is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Mupirocin ointment", "Oral Vancomycin", "Oral Cephalexin", "Topical Ketoconazole cream", "Intravenous Ampicillin"]'::jsonb, 0, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 19-year-old girl is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Post-streptococcal Glomerulonephritis (PSGN)", "Scarlet Fever", "Streptococcal toxic shock syndrome", "Acute glomerulonephritis and carditis", "Acute Rheumatic Fever (ARF)"]'::jsonb, 0, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 22-year-old male toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["Desmoglein 3", "Type VII Collagen", "Desmocollin 1", "BP180 (Type XVII Collagen)", "Desmoglein 1"]'::jsonb, 4, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.'),
    (v_topic_id, 'A homeless female presents with a painful, deep, ''punched-out'' ulcer covered by a thick, adherent greenish-yellow crust on their lower leg. The border of the ulcer is violaceous and indurated. Culture grows Streptococcus pyogenes. What is the diagnosis?', '["Non-bullous Impetigo", "Necrotizing Fasciitis", "Erysipelas", "Pyoderma Gangrenosum", "Ecthyma"]'::jsonb, 4, 'Ecthyma is a deep, dermal extension of impetigo, often referred to as ''deep impetigo.'' It typically begins as a superficial vesicle or pustule that penetrates through the epidermis into the dermis, leaving a characteristic ''punched-out'' ulcer covered by a thick, hard, adherent crust that heals with scarring. Group A Strep and S. aureus are the primary causes.'),
    (v_topic_id, 'A 72-year-old girl presents with a sudden onset of a bright red, painful, warm rash on their left cheek that is rapidly expanding. It is accompanied by high fever and chills. Physical exam shows a fiery red, indurated, swollen plaque with a palpable, sharply demarcated, raised border on the malar area. What is the most likely causative organism?', '["Mycobacterium marinum", "Staphylococcus aureus", "Bartonella henselae", "Streptococcus pyogenes (Group A Strep)", "Pseudomonas aeruginosa"]'::jsonb, 3, 'This patient has erysipelas, a superficial variant of cellulitis characterized by prominent lymphatic involvement, a fiery-red hue, and a sharply demarcated, raised, palpable border. The classic facial/malar distribution is highly characteristic. Streptococcus pyogenes (Group A Beta-hemolytic Strep) is the overwhelming cause of erysipelas.'),
    (v_topic_id, 'A 68-year-old man with a history of poorly controlled type 2 diabetes presents with a warm, red, swollen right lower leg. Physical examination reveals diffuse, ill-defined erythema, warmth, and tenderness of the calf. No crepitus, fluctuance, or systemic toxicity is noted. Fissuring is present in the interdigital spaces of the toes (tinea pedis). What is the primary clinical feature distinguishing this condition from erysipelas?', '["The presence of prominent lymphatic streaking", "Successful treatment with penicillin instead of cephalexin", "Ill-defined, non-palpable borders and involvement of the deep dermis and subcutaneous fat", "The presence of high fever and leukocytosis", "The rapid, hyperacute spread within hours"]'::jsonb, 2, 'This patient has cellulitis, an infection of the deep dermis and subcutaneous tissue. Unlike erysipelas (which is superficial, bright red, and has sharply demarcated, raised borders), cellulitis classically has ill-defined, flat borders, is a deeper pink/red, and frequently enters through skin barrier breakdowns like tinea pedis.'),
    (v_topic_id, 'A 45-year-old girl presents to the emergency department with excruciating, deep pain in their left thigh that is completely ''out of proportion'' to the mild, diffuse erythema seen on skin examination. Within hours, the leg becomes extremely swollen and indurated, and dusky, purplish patches with tense bullae begin to form. Vitals show T 39.8 C, HR 125, BP 82/48 mmHg. What is the most critical and immediate next step in management?', '["Start high-dose intravenous Piperacillin-Tazobactam and Vancomycin", "Obtain double-volume blood cultures and wait for the results", "Order an urgent MRI of the left lower extremity with contrast", "Apply high-potency topical steroids to reduce local inflammation", "Emergent surgical consultation for exploratory debridement"]'::jsonb, 4, 'This patient has necrotizing fasciitis, a rapidly progressive, life-threatening surgical emergency. The classic early clue is pain out of proportion to physical exam findings, progressing quickly to dusky discoloration, woody induration, crepitus, and septic shock. While broad-spectrum antibiotics are critical, the single most important and prognostic step is immediate surgical debridement of necrotic tissue.'),
    (v_topic_id, 'A obese 25-year-old girl complains of a dark, non-itchy, slightly scaly rash in their bilateral armpits and groin that has been present for several months. Physical exam shows well-demarcated, reddish-brown, thin plaques. Wood''s lamp examination of the axillary vault demonstrates a brilliant ''coral-red'' fluorescence. What is the causative organism?', '["Candida albicans", "Corynebacterium minutissimum", "Malassezia furfur", "Trichophyton rubrum", "Staphylococcus aureus"]'::jsonb, 1, 'This is Erythrasma, a superficial bacterial infection of the intertriginous skin caused by Corynebacterium minutissimum (a Gram-positive rod). It closely mimics tinea or inverse psoriasis but is identified by its brilliant coral-red fluorescence under Wood''s lamp, which is caused by the bacterial production of coproporphyrin III. It responds well to topical erythromycin or clindamycin.'),
    (v_topic_id, 'A 12-year-old woman athlete complains of extremely foul-smelling feet. Physical exam of the soles reveals sweaty skin with dozens of small, shallow, 1-3 mm punched-out pits or craters on the weight-bearing areas of the bilateral heels and soles. What is the pathophysiology driving the formation of these characteristic pits?', '["Autoimmune-mediated destruction of plantar sweat ducts", "Mechanical erosion from repetitive friction and hyperhidrosis", "Superficial invasion of dermatophytes into the sweat glands", "A chronic contact allergy to rubber compounds in athletic shoes", "Bacterial production of extracellular proteases that digest the stratum corneum"]'::jsonb, 4, 'This patient has Pitted Keratolysis, a superficial bacterial infection of the soles caused by Kytococcus sedentarius, Dermatophilus congolensis, or Actinomyces. It thrives in warm, wet environments (hyperhidrosis). The bacteria produce extracellular proteases that degrade keratin, digesting the stratum corneum to create characteristic punched-out pits. The foul odor (bromhidrosis) is due to sulfur byproducts.'),
    (v_topic_id, 'A 22-year-old girl develops a highly pruritic, bumpy rash on their back and buttocks 36 hours after using a hotel hot tub. Physical examination shows multiple erythematous follicular papules and pustules concentrated primarily under the areas covered by their swimwear. What is the typical clinical course of this condition?', '["It is self-limited and usually resolves spontaneously within 7-10 days without specific treatment", "It is highly contagious and spreads to family members through air droplets", "It is caused by a type IV hypersensitivity reaction to chlorine", "It requires immediate oral Ciprofloxacin to prevent systemic bacteremia", "It leads to chronic, scarred alopecia of the affected hair follicles"]'::jsonb, 0, 'This is Hot Tub Folliculitis, caused by Pseudomonas aeruginosa, which thrives in warm, wet, poorly chlorinated environments. It presents as itchy follicular pustules beneath swimwear due to occlusion. In immunocompetent hosts, the infection is self-limited and resolves spontaneously in 7-10 days with simple supportive care.'),
    (v_topic_id, 'A 72-year-old rancher presents with a painless, black, sunken sore on their forearm. They note that several of their cattle recently died unexpectedly on the farm. Physical exam reveals a 2.5 cm central black necrotic eschar surrounded by a ring of non-pitting gelatinous edema and small vesicles. What is the primary drug of choice for the treatment of this condition?', '["Topical Permethrin 5% cream", "Ciprofloxacin or Doxycycline", "Intravenous Ganciclovir", "Oral Griseofulvin", "Oral Valacyclovir"]'::jsonb, 1, 'This patient has Cutaneous Anthrax, caused by Bacillus anthracis spores entering through skin abrasions, classically from handling infected animal products (wool, hides, cattle). The pathognomonic lesion is a painless black eschar surrounded by extensive edema. Fluoroquinolones (Ciprofloxacin) or Doxycycline are the first-line treatments of choice.'),
    (v_topic_id, 'An 8-year-old child presents with an expanding scaly patch of hair loss on the back of his scalp. Physical exam shows well-demarcated alopecia studded with ''black dots'' (hairs broken at the surface of the scalp) and occipital lymphadenopathy. A KOH prep confirms endothrix spores. What is the most common causative organism of this condition in the United States?', '["Malassezia furfur", "Trichophyton tonsurans", "Candida albicans", "Trichophyton rubrum", "Microsporum canis"]'::jsonb, 1, 'Tinea capitis is the most common pediatric dermatophyte infection in the US, and Trichophyton tonsurans is the leading causative organism (responsible for >90% of US cases). It characteristically causes ''black dot'' alopecia because the endothrix (internal) fungal spores weaken the hair shaft, causing it to break off flush with the scalp.'),
    (v_topic_id, 'A 6-year-old girl is diagnosed with tinea capitis. Which of the following is the most appropriate first-line treatment for this patient?', '["Topical Clobetasol propionate ointment", "Oral Griseofulvin or oral Terbinafine", "Topical Terbinafine 1% cream", "Oral Amoxicillin-Clavulanate", "Topical Ketoconazole 2% shampoo daily"]'::jsonb, 1, 'Tinea capitis MUST be treated with systemic (oral) antifungal therapy (such as oral Griseofulvin or oral Terbinafine) because the dermatophyte invades deep into the hair follicle and shaft, where topical creams and shampoos cannot penetrate. Topical shampoos (like ketoconazole or selenium sulfide) are only used as adjunctive therapy to reduce spore shedding.'),
    (v_topic_id, 'A 7-year-old boy with untreated tinea capitis develops a large, painful, boggy, pus-filled mass on his scalp. He is febrile (38.3 C) and has tender cervical lymphadenopathy. Hairs in the boggy area pull out easily and painlessly. What is the primary pathogenesis of this lesion (Kerion)?', '["A secondary, deep Staphylococcus aureus bacterial abscess (superinfection)", "An intense, host T-cell-mediated hypersensitivity reaction to the dermatophyte", "A neoplastic proliferation of follicular dendritic cells", "Direct fungal invasion into the meninges and skull bone", "A congenital vascular malformation triggered by inflammation"]'::jsonb, 1, 'A Kerion is a severe, highly inflammatory form of tinea capitis. It represents an intense host cell-mediated (T-cell) hypersensitivity reaction to the dermatophyte, not a secondary bacterial abscess. It is characterized by a painful, boggy, purulent mass. Incision and drainage (I&D) is contraindicated; treatment requires oral antifungals and occasionally systemic corticosteroids.'),
    (v_topic_id, 'A 12-year-old high-school wrestler presents with several extremely itchy, ring-shaped rashes on their arms and chest. Physical exam shows annular erythematous plaques with a scaly, active, advancing border and central clearing. A KOH preparation from the active scale shows branching, septate hyphae. What is the most common causative organism of this condition worldwide?', '["Microsporum canis", "Malassezia furfur", "Trichophyton tonsurans", "Candida albicans", "Trichophyton rubrum"]'::jsonb, 4, 'This is Tinea Corporis (ringworm), characterized by classic annular plaques with an active scaly border. Trichophyton rubrum is the most common dermatophyte worldwide, causing tinea corporis, tinea pedis, and tinea cruris.'),
    (v_topic_id, 'A 22-year-old male presents with a highly pruritic, red rash in his groin. Physical examination reveals bilateral, symmetric, scaly erythematous plaques in the inguinal folds. Crucially, the scrotum is completely spared. What is a key clinical feature distinguishing this condition from intertriginous Candidiasis?', '["Dermatophytes (tinea cruris) typically spare the scrotum, whereas Candidiasis frequently involves the scrotum", "Tinea cruris requires oral antibiotics, whereas Candidiasis is self-limiting", "Candidiasis shows branching septate hyphae on KOH, whereas tinea shows budding yeast", "Tinea cruris is never itchy, while Candidiasis is extremely painful", "Tinea cruris presents with satellite pustules, whereas Candidiasis does not"]'::jsonb, 0, 'Tinea Cruris (''jock itch'') is a dermatophyte infection of the groin. A key clinical diagnostic clue that distinguishes it from Candidal intertrigo is that tinea cruris characteristically spares the moist skin of the scrotum and penis, whereas Candidiasis frequently involves the scrotum with confluent erythema and satellite pustules.'),
    (v_topic_id, 'A 45-year-old boy presents with chronic, dry, scaly skin on the soles and lateral sides of both feet. They have been applying moisturizing lotions for months without improvement. Physical exam shows fine, dry, silvery-white scale in a ''moccasin'' distribution. KOH prep of the scale is positive. What other anatomic site should be closely inspected to confirm the classic ''two feet, one hand'' syndrome associated with this organism?', '["The palms of the hands (typically only one palm is affected)", "The oral cavity for white plaques", "The fingernails of the non-dominant hand", "The scalp for black dot alopecia", "The axillae for coral-red fluorescence"]'::jsonb, 0, 'Moccasin-type tinea pedis is chronically caused by Trichophyton rubrum. It is highly associated with ''Two Feet, One Hand'' syndrome, where both feet are chronically scaly and infected, but only ONE hand (typically the dominant hand used to scratch the feet) shows unilateral scaling (tinea manuum). Checking the palms is an important clinical pearl.'),
    (v_topic_id, 'A 19-year-old female has been applying a high-potency topical steroid (Clobetasol) for a suspected eczematous rash on her lower leg. Over 3 weeks, she notes the rash is expanding and now has deep, painful bumps. Exam shows an erythematous, scaly plaque studded with follicular papules and nodules. Biopsy confirms fungal hyphae within the hair follicle and surrounding dermis. What is the diagnosis?', '["Sporotrichosis", "Kerion", "Cellulitis", "Majocchi''s Granuloma", "Erythema Nodosum"]'::jsonb, 3, 'Majocchi''s Granuloma is a deep, suppurative folliculitis caused by dermatophytes invading into the dermis and hair follicle, classically precipitated by the inappropriate application of topical corticosteroids to a superficial tinea infection. The steroids suppress local immunity, allowing the fungus to penetrate deeply. It requires systemic oral antifungal therapy (e.g., terbinafine) to cure.'),
    (v_topic_id, 'A 65-year-old girl presents with yellow, thickened, crumbling toenails. A PAS stain of nail clippings confirms a dermatophyte infection. The patient is healthy but has mild chronic liver disease (compensated). You decide to start oral Terbinafine. What is the recommended duration of therapy for toenail onychomycosis, and what monitoring is required?', '["1 week of oral Terbinafine; no monitoring is required", "12 weeks of oral Terbinafine; baseline and periodic Liver Function Tests (LFTs) must be monitored", "12 weeks of oral Terbinafine; periodic Renal Function Tests must be monitored", "6 weeks of oral Terbinafine; no laboratory monitoring is required", "12 months of oral Terbinafine; CBC must be monitored weekly"]'::jsonb, 1, 'Toenail onychomycosis requires 12 weeks of oral Terbinafine therapy (fingernails require 6 weeks). Because oral terbinafine can cause hepatotoxicity, baseline and periodic monitoring of transaminases (LFTs) is mandatory, especially in patients with pre-existing liver history.'),
    (v_topic_id, 'A young girl returns from a beach vacation and notices multiple white, non-tanning spots on their upper back and chest. The spots are slightly itchy when the patient sweats. Physical exam shows multiple small, confluent, hypopigmented macules with a very fine, powdery scale. A KOH preparation from the scale demonstrates short, thick hyphae and clusters of round yeast cells (''spaghetti and meatballs''). What chemical produced by the yeast is responsible for these hypopigmented lesions?', '["Uric acid", "Lactic acid", "Melanin", "Coproporphyrin III", "Azelaic acid"]'::jsonb, 4, 'This is Tinea Versicolor (Pityriasis Versicolor), caused by the lipophilic yeast Malassezia (M. furfur). The yeast produces azelaic acid, a dicarboxylic acid that biochemically inhibits tyrosinase, an essential enzyme in the melanin synthesis pathway of melanocytes. This leads to decreased melanin production and the classic hypopigmented spots that fail to tan.'),
    (v_topic_id, 'An infant presents with a bright, beefy-red diaper rash. Physical examination reveals confluent, bright red, moist plaques involving the inguinal folds, with multiple pinpoint erythematous ''satellite'' pustules and papules scattered outside the primary border of the rash. What is the classic finding on KOH preparation?', '["Pseudohyphae and budding yeast cells", "Gram-positive rods in chains", "Spherules containing endospores", "Branching, septate hyphae", "Henderson-Paterson bodies"]'::jsonb, 0, 'This is Candidal Diaper Dermatitis, caused by Candida albicans. Key diagnostic features are the involvement of the inguinal folds (which are spared in irritant contact diaper dermatitis) and the presence of satellite pustules. The classic KOH preparation finding for Candida is pseudohyphae and budding yeast (blastoconidia).'),
    (v_topic_id, 'A dishwasher presents with a swollen, red, painful nail fold at the base of her right middle fingernail that has been present for 3 weeks. Physical exam shows erythema and edema of the proximal nail fold with complete loss of the cuticle. Gentle pressure expresses a small amount of thick white material. What is the primary causative organism and the most important management strategy?', '["Staphylococcus aureus; immediate incision and drainage (I&D) and oral Cephalexin", "Trichophyton rubrum; oral Terbinafine for 12 weeks", "Herpes Simplex Virus; oral Acyclovir", "Pseudomonas aeruginosa; soak in diluted bleach daily", "Candida albicans; strict water avoidance (keeping hands dry) and topical/oral antifungals"]'::jsonb, 4, 'This is Chronic Paronychia, which is primarily a multifactorial inflammatory reaction to moisture and irritants (frequent wet work like dishwashing) colonized by Candida albicans. Unlike acute bacterial paronychia (usually Staph, sudden, treated with drainage/antibiotics), chronic paronychia persists for weeks and requires strict water avoidance and topical/oral antifungals.'),
    (v_topic_id, 'A 78-year-old florist presents with a non-healing, painless bump on their right index finger. Over the past 2 weeks, several new, painless subcutaneous nodules have appeared in a linear pattern extending up the right forearm along the lymphatic drainage path. Biopsy of a nodule shows yeast cells that are characteristically ''cigar-shaped'' on culture. What is the diagnosis?', '["Leishmaniasis", "Majocchi''s Granuloma", "Cutaneous Anthrax", "Sporotrichosis", "Blastomycosis"]'::jsonb, 3, 'This is Sporotrichosis, caused by the dimorphic fungus Sporothrix schenckii (classic ''Rose Gardener''s Disease''). It is acquired through traumatic inoculation from contaminated soil, thorns (especially rose thorns), or sphagnum moss. It characteristically presents with a primary inoculation chancre followed by secondary subcutaneous nodules along the lymphatic drainage path (lymphocutaneous/sporotrichoid spread). Histology shows cigar-shaped budding yeast.'),
    (v_topic_id, 'A 45-year-old woman recently moved to the desert of southern Arizona and developed a high fever, a dry cough, joint pain, and multiple painful, warm, red nodules on their bilateral shins (erythema nodosum). Histopathological examination of a lung biopsy reveals large, thick-walled spherules filled with numerous small endospores. What is the diagnosis?', '["Histoplasmosis", "Sporotrichosis", "Blastomycosis", "Tinea Versicolor", "Coccidioidomycosis"]'::jsonb, 4, 'Coccidioidomycosis (''Valley Fever'') is caused by the soil fungus Coccidioides immitis, which is endemic to the arid Southwestern United States. Primary infection is pulmonary (fever, cough), often accompanied by reactive immunological skin manifestations like Erythema Nodosum (painful nodules on the shins) and Erythema Multiforme. The diagnostic tissue form is the thick-walled spherule containing endospores.'),
    (v_topic_id, 'A 68-year-old man from the Ohio River Valley presents with a large, chronic, verrucous (warty) plaque with a sharp, violaceous border and small micro-abscesses at the edge on their cheek. They also report a chronic cough and weight loss. A biopsy of the skin lesion reveals large yeast cells that exhibit ''broad-based budding'' under the microscope. What is the causative organism?', '["Blastomyces dermatitidis", "Sporothrix schenckii", "Histoplasma capsulatum", "Candida albicans", "Coccidioides immitis"]'::jsonb, 0, 'Blastomycosis, caused by Blastomyces dermatitidis, is endemic to the Ohio and Mississippi River Valleys and the Great Lakes region. Inhalation of spores leads to pulmonary disease, which can disseminate to the skin, presenting as verrucous (warty) or ulcerative plaques with micro-abscesses. The pathognomonic histologic finding is large, thick-walled yeast with broad-based budding.'),
    (v_topic_id, 'An HIV-positive patient with a CD4 count of 45/mm3 presents with fever, weight loss, and dozens of small, red, dome-shaped papules on their face and trunk, some of which exhibit central dimpling, mimicking molluscum contagiosum. A biopsy of a skin lesion shows numerous tiny, 2-4 micron, oval intracellular yeast cells residing inside macrophages. What is the classic environmental reservoir for this pathogen?', '["Decaying wood and organic matter near rivers", "Soil contaminated with bird or bat droppings (caves, chicken coops)", "Infected sheep and livestock", "Public swimming pools and fish tanks", "Arid desert sand of the Southwest US"]'::jsonb, 1, 'This patient has disseminated Histoplasmosis, which occurs in immunocompromised individuals (like HIV patients with low CD4). Cutaneous lesions can mimic molluscum contagiosum. Histology shows tiny intracellular yeast within macrophages (histiocytes). The environmental reservoir for Histoplasma capsulatum is soil enriched with nitrogen-rich bird or bat droppings (found in caves, chicken coops, etc.).'),
    (v_topic_id, 'A 17-year-old boy presents with a sudden, explosive outbreak of hundreds of painful, ''punched-out'', monomorphic, crusted erosions and fluid-filled blisters overlying pre-existing atopic dermatitis on their face, neck, and upper chest. The patient is febrile (39.0 C) and has severe lymphadenopathy. What is the diagnosis?', '["Eczema Herpeticum (Kaposi varicelliform eruption)", "Disseminated Molluscum Contagiosum", "Acute Generalized Exanthematous Pustulosis (AGEP)", "Bullous Impetigo", "Toxic Epidermal Necrolysis (TEN)"]'::jsonb, 0, 'Eczema Herpeticum is a severe, widespread cutaneous viral infection caused by Herpes Simplex Virus (usually HSV-1) infecting skin affected by an active dermatosis, most classically Atopic Dermatitis. It is a medical emergency characterized by high fever, adenopathy, and a sudden crop of painful, monomorphic, ''punched-out'' circular erosions that can lead to severe systemic infection or ocular complications.'),
    (v_topic_id, 'A 22-year-old man presents with severe, burning pain on the right side of their chest. Forty-eight hours later, a highly pruritic and painful rash of grouped, fluid-filled blisters on a red base emerges. The rash follows a single dermatome (T5) on the right side and does not cross the midline of the body. Where does the causative virus reside in a latent state between the primary chickenpox infection and this reactivation?', '["Langerhans cells in the dermis", "Keratinocytes of the basal epidermis", "Splenic macrophages", "Dorsal root ganglion (Sensory nerve ganglion)", "Trigeminal ganglion"]'::jsonb, 3, 'This is Herpes Zoster (shingles), caused by the reactivation of latent Varicella-Zoster Virus (VZV). Between primary varicella (chickenpox) and zoster, the virus remains dormant (latent) inside the sensory nerve cell bodies of the dorsal root ganglia (for spinal nerves) or cranial nerve ganglia.'),
    (v_topic_id, 'A 68-year-old woman presents with a shingles outbreak on the right side of their forehead and nose. During physical examination, the clinician notes several painful shingles blisters on the very tip and side of the patient''s nose. What is the clinical name of this sign, and what is its immediate significance?', '["Nikolsky sign; it indicates severe epidermal detachment and SJS", "Henderson sign; it indicates a poxvirus superinfection", "Ramsay Hunt sign; it indicates a high risk of facial nerve palsy and hearing loss", "Koebner sign; it indicates the shingles was triggered by local scratching", "Hutchinson sign; it indicates involvement of the nasociliary branch of CN V1, representing a high risk of ocular (eye) involvement"]'::jsonb, 4, 'The Hutchinson sign refers to vesicles located on the tip or side of the nose during a shingles outbreak involving the ophthalmic division of the trigeminal nerve (CN V1). This indicates that the nasociliary nerve is involved, which also supplies the structures of the eye. Its presence carries a high risk of ophthalmic zoster and permanent eye damage, requiring an urgent ophthalmology consult.'),
    (v_topic_id, 'A patient presents with shingles blisters on the right face. They also complain of severe ear pain, dizziness, a spinning sensation, and they are completely unable to close their right eye or smile on the right side. Vesicles are visible in the external auditory canal. What is the diagnosis?', '["Nicolau Syndrome", "Meniere''s disease with HSV-1 outbreak", "Bell''s palsy with secondary ear infection", "Ramsay Hunt Syndrome (Herpes Zoster Oticus)", "Gorlin Syndrome"]'::jsonb, 3, 'Ramsay Hunt Syndrome (Herpes Zoster Oticus) occurs due to VZV reactivation inside the geniculate ganglion of the facial nerve (CN VII). The classic triad is ipsilateral facial nerve paralysis (causing facial droop and inability to close the eye), severe otalgia (ear pain), and vesicles inside the external auditory canal and auricle, often accompanied by vestibulocochlear symptoms (dizziness, tinnitus, hearing loss).'),
    (v_topic_id, 'A 5-year-old child presents with dozens of small, skin-colored, shiny bumps on his chest and arms. Physical exam shows small (2-5 mm), firm, dome-shaped papules with a distinct central dimple (umbilication). A cheesy plug can be easily expressed from the center. What is the classic finding on histopathological examination of a biopsy?', '["Acantholysis with a ''fishnet'' immunofluorescence pattern", "Multinucleated giant cells with ballooning degeneration of the epidermis", "Massive pseudoepitheliomatous hyperplasia with microabscesses", "A dense septal panniculitis without vasculitis", "Intracytoplasmic eosinophilic inclusion bodies (Henderson-Paterson bodies) within keratinocytes"]'::jsonb, 4, 'This is Molluscum Contagiosum, caused by a double-stranded DNA poxvirus. The lesions are clinically characterized by firm, dome-shaped, umbilicated papules. Histology pathognomonically shows Henderson-Paterson bodies, which are massive, oval, intracytoplasmic eosinophilic inclusion bodies that compress the host keratinocyte nucleus.'),
    (v_topic_id, 'A 10-year-old child has several rough, cauliflower-like bumps on his fingers. Physical examination reveals hyperkeratotic, exophytic papules with multiple tiny black dots on the surface. What do these characteristic ''black dots'' represent?', '["Sites of focal melanin deposition within the basal layer", "Thrombosed, clotted capillaries supplying the rapidly growing wart tissue", "Necrotic nuclei of basal cells killed by the HPV virus", "Trap-door collection of dirt and environmental debris", "Viral spores embedded in the stratum corneum"]'::jsonb, 1, 'This is Verruca vulgaris (common wart), caused by Human Papillomavirus (HPV). Paring down the hyperkeratotic surface of a wart reveals characteristic tiny black dots. These represent thrombosed, clotted capillaries that are pulled vertically toward the surface by the rapidly proliferating epidermal tissue to supply blood to the wart.'),
    (v_topic_id, 'A patient presents with a painful, deep bump on the ball of their right foot that makes them feel like they are ''walking on a pebble.'' On examination, there is a thick, flat hyperkeratotic plaque. How can you clinically distinguish this plantar wart (Verruca plantaris) from a simple foot callus?', '["Calluses show pinpoint bleeding upon paring and are only painful with direct pressure", "Warts fluoresce coral-red under a Wood''s lamp, whereas calluses do not", "Warts are soft and fluctuant, whereas calluses are rock-hard", "Warts show pinpoint bleeding upon paring and are more painful with lateral (side-to-side) squeezing than direct pressure", "There is no reliable clinical difference; a biopsy is always required"]'::jsonb, 3, 'To clinically differentiate a plantar wart from a callus: paring down a plantar wart removes the hard keratin to reveal thrombosed capillaries that bleed as pinpoints, whereas calluses contain only flat layers of dead skin. Additionally, warts are classically much more painful when squeezed from side-to-side (lateral pressure) than when pressed directly, whereas calluses are painful with direct downward pressure.'),
    (v_topic_id, 'A 24-year-old veterinary student presents with a single, large, painless, targetoid nodule on his right thumb. He notes he recently helped deliver lambs on a farm. On exam, there is a 1.8 cm targetoid nodule with a gray-white necrotic center, a violaceous middle ring, and a bright red outer inflammatory halo. What is the causative virus?', '["Human Papillomavirus", "Orf virus (a parapoxvirus)", "Herpes Simplex Virus", "Coxsackievirus A16", "Bacillus anthracis"]'::jsonb, 1, 'This is Orf (also known as Ecthyma contagiosum), a zoonotic infection caused by a parapoxvirus. It is transmitted to humans through direct contact with infected sheep or goats (classically veterinarians, farm hands, or shearers). It presents as a single, painless, targetoid nodule that goes through six stages, resolving spontaneously within 6-8 weeks.'),
    (v_topic_id, 'A 3-year-old child presents with a low-grade fever and small, painful blisters in his mouth and on his palms and soles. Physical examination shows multiple small vesicles and ulcers in the oral cavity, and unique, elongated, ''football-shaped'' greyish vesicles with a red halo on the hands and feet. What is the most common causative agent of this condition, and what is a classic late complication in children?', '["Coxsackievirus A16; painless nail shedding (Onychomadesis) weeks later", "Parvovirus B19; aplastic crisis in healthy children", "Herpes Simplex Virus 1; permanent scarring alopecia", "HHV-6; febrile seizures leading to epilepsy", "Sarcoptes scabiei; post-infectious glomerulonephritis"]'::jsonb, 0, 'This is Hand-Foot-and-Mouth Disease (HFMD), most commonly caused by Coxsackievirus A16 (or Enterovirus 71). It presents with painful oral erosions and greyish, football-shaped vesicles on the palms and soles. A well-known, benign late complication that occurs 2-6 weeks after the illness is Onychomadesis (painless shedding and loss of the nails).'),
    (v_topic_id, 'A 6-year-old child is brought to the clinic with bright, fiery-red cheeks. His mother reports he had a mild runny nose and low-grade fever last week, which resolved. On exam, the child has a distinct ''slapped cheek'' facial rash and a lacy, reticulated, pink rash on his limbs and trunk. What is the causative agent, and what is the primary risk of this infection in a patient with Sickle Cell Disease?', '["Coxsackievirus A16; causing severe viral meningitis", "Measles virus; leading to subacute sclerosing panencephalitis (SSPE)", "HHV-6; inducing status epilepticus", "Parvovirus B19; precipitating an acute Aplastic Crisis", "Streptococcus pyogenes; leading to acute rheumatic fever"]'::jsonb, 3, 'This is Fifth Disease (Erythema Infectiosum), caused by Parvovirus B19. It classically presents with a ''slapped cheek'' rash followed by a lacy, reticulated eruption on the body. Because Parvovirus B19 directly infects and destroys erythroid progenitor cells in the bone marrow, it temporarily halts red blood cell production. In patients with high RBC turnover (like Sickle Cell Disease or hereditary spherocytosis), this can precipitate a life-threatening acute Aplastic Crisis.'),
    (v_topic_id, 'An 18-month-old child presents with a sudden pink rash. The mother notes the child had a very high fever (40.0 C) for exactly 3 days, during which the child was irritable but otherwise well. Today, the fever broke suddenly, and within hours, a non-itchy rash of rose-pink macules emerged on the trunk and spread to the neck and limbs. What is the diagnosis?', '["Rubella (German Measles)", "Rubeola (Measles)", "Erythema Infectiosum (Fifth Disease)", "Roseola Infantum (Exanthem Subitum)", "Scarlet Fever"]'::jsonb, 3, 'Roseola Infantum (Exanthem Subitum) is caused by Human Herpesvirus 6 (HHV-6) (or HHV-7). It classically affects infants and presents with a sudden very high fever (often >39.5 C) lasting 3-5 days, which can trigger febrile seizures. Characteristically, as soon as the fever suddenly drops (defervescence), a rose-pink maculopapular rash immediately erupts on the trunk and spreads outward, resolving within 1-2 days.'),
    (v_topic_id, 'An elderly patient with advanced dementia residing in a nursing home presents with thick, yellow-gray, ''rock-hard'', hyperkeratotic scales and crusts on her hands, feet, and scalp. She does not complain of itching. A skin scraping demonstrates millions of active mites. What is the recommended treatment regimen for this condition?', '["Oral Griseofulvin for 12 weeks", "High-dose intravenous antibiotics and surgical debridement of the scales", "Strict isolation and daily washing with soap and water", "Combination therapy: Oral Ivermectin (multiple doses) plus topical Permethrin 5% cream", "Topical Permethrin 5% cream alone applied once"]'::jsonb, 3, 'This is Crusted (Norwegian) Scabies, an extremely contagious variant of scabies occurring in immunocompromised, elderly, or neurologically impaired patients who cannot scratch (which normally keeps mite numbers low). The skin is packed with millions of mites. Due to the massive mite burden and thick hyperkeratotic crusts, topicals alone often fail. The standard treatment is combination therapy: multiple doses of oral Ivermectin (typically days 1, 2, 8, 9, 15) plus daily topical Permethrin 5% cream.'),
    (v_topic_id, 'A patient returns from a Caribbean vacation where they walked barefoot on the beach. They present with an extremely itchy, red, ''snake-like'' wavy line on the dorsum of their right foot. The patient notes the red line seems to advance about 1 cm each day. What is the causative organism?', '["Dracunculus medinensis", "Ancylostoma braziliense (animal hookworm)", "Leishmania tropica", "Strongyloides stercoralis", "Sarcoptes scabiei"]'::jsonb, 1, 'This is Cutaneous Larva Migrans (''creeping eruption''), caused by the larvae of animal hookworms (most commonly Ancylostoma braziliense, which infects cats and dogs). Humans are accidental hosts; the larvae penetrate bare skin (classically on beaches contaminated with animal feces) but lack the enzymes to penetrate the human basement membrane to enter the bloodstream. They are trapped in the epidermis, tunneling aimlessly to create a highly pruritic, serpiginous (wavy) track that moves daily.'),
    (v_topic_id, 'A patient presents with intense itching on their abdomen and groin. Physical exam reveals broad, flat-bodied lice firmly attached to the base of the pubic hairs, and multiple 0.5 cm asymptomatic, slate-blue macules (maculae ceruleae) scattered across the lower abdomen and upper thighs. What is the cause of these unique blue spots?', '["A secondary deep fungal infection within the pubic follicles", "Deep dermal deposition of blue melanin pigment by activated melanocytes", "A congenital vascular anomaly flared by the infestation", "Localized vascular thrombosis in the superficial capillaries caused by scratching", "A chemical conversion of host hemoglobin to biliverdin by the salivary enzymes of the feeding pubic louse"]'::jsonb, 4, 'This patient has pubic lice (''crabs''), caused by Pthirus pubis. The pathognomonic slate-blue or greyish-blue spots (Maculae ceruleae) on the lower abdomen, pelvis, or thighs are caused by the anticoagulant salivary secretions of the feeding louse, which enzymatically convert host red blood cell hemoglobin into biliverdin within the local dermis.'),
    (v_topic_id, 'A soldier returning from a tour in the Middle East presents with a painless, crusty, non-healing ulcer on their cheek that has been present for 2 months. Physical exam shows a firm, erythematous, indurated plaque that has ulcerated in the center, resembling a ''small volcano.'' Biopsy of the border reveals tiny amastigotes within dermal macrophages. How is this pathogen transmitted?', '["Contact with contaminated sheep or goats", "Barefoot contact with beach sand", "Bite of an infected Phlebotomine Sandfly", "Inhalation of dry bird droppings", "Bite of an infected Ixodes Tick"]'::jsonb, 2, 'This is Cutaneous Leishmaniasis, a protozoan infection caused by Leishmania species. It is endemic to the Middle East, North Africa, and parts of South/Central America. It is transmitted to humans by the bite of an infected female Phlebotomine Sandfly. The classic lesion is a painless, chronic, warty, or ''volcano-like'' ulcer that shows intracellular amastigotes (Leishman-Donovan bodies) inside macrophages.'),
    (v_topic_id, 'A traveler complains of waking up with multiple highly pruritic red bumps in linear clusters of 3 to 5 on their arms and neck. The patient refers to this as the ''breakfast, lunch, and dinner'' pattern. Which of the following pests is classic for this sequential bite distribution?', '["Ancylostoma braziliense (Hookworm)", "Ixodes scapularis (Ticks)", "Sarcoptes scabiei (Scabies)", "Cimex lectularius (Bedbugs)", "Pthirus pubis (Pubic lice)"]'::jsonb, 3, 'Bedbug bites (caused by Cimex lectularius) characteristically present as highly itchy, erythematous papules arranged in a linear row or cluster of three (sometimes more), colloquially termed the ''breakfast, lunch, and dinner'' sign. This pattern occurs because the bedbug is disturbed during feeding and bites sequentially along the skin.'),
    (v_topic_id, 'A 22-year-old boy who maintains a freshwater home aquarium presents with a chronic, non-healing, warty plaque on their right index finger. Over the past 2 months, several similar nodules have developed in a linear pattern up the arm. Fungal cultures are negative. A tissue biopsy shows acid-fast bacilli on Ziehl-Neelsen stain. What is the diagnosis?', '["Erysipeloid", "Mycobacterium marinum infection (Swimming Pool/Fish Tank Granuloma)", "Cutaneous Leishmaniasis", "Sporotrichosis", "Blastomycosis"]'::jsonb, 1, 'Mycobacterium marinum is an atypical (nontuberculous) mycobacterium found in fresh and salt water. It causes ''fish tank granuloma'' or ''swimming pool granuloma,'' acquired through minor skin trauma during aquarium cleaning or swimming. It presents as a warty nodule/plaque that can show sporotrichoid (lymphocutaneous) spread up the arm. The organism is acid-fast positive, distinguishing it from Sporothrix.'),
    (v_topic_id, 'A 38-year-old man is brought to the clinic with several itchy, honey-colored crusted sores around their nose and mouth. The patient is otherwise active and afebrile. A skin swab culture grows Staphylococcus aureus. Which of the following is the most appropriate first-line treatment for this patient?', '["Intravenous Ampicillin", "Topical Ketoconazole cream", "Topical Mupirocin ointment", "Oral Vancomycin", "Oral Cephalexin"]'::jsonb, 2, 'This patient has localized non-bullous impetigo, characterized by characteristic honey-colored (golden) crusts. For localized disease, first-line therapy is topical antibiotics, such as Mupirocin or Retapamulin. If the lesions are widespread or systemic symptoms are present, oral antibiotics like cephalexin are preferred.'),
    (v_topic_id, 'A 72-year-old man is diagnosed with widespread impetigo caused by a nephritogenic strain of Group A Beta-hemolytic Streptococcus. Despite prompt and appropriate antibiotic treatment with oral cephalexin, what serious non-suppurative complication of this skin infection is NOT prevented by antibiotic therapy?', '["Post-streptococcal Glomerulonephritis (PSGN)", "Scarlet Fever", "Streptococcal toxic shock syndrome", "Acute Rheumatic Fever (ARF)", "Acute glomerulonephritis and carditis"]'::jsonb, 0, 'While antibiotics prevent Acute Rheumatic Fever when treating streptococcal pharyngitis, they do NOT prevent Post-streptococcal Glomerulonephritis (PSGN) following either pharyngeal or cutaneous streptococcal infections. PSGN typically presents with hematuria (''tea-colored'' urine), hypertension, and periorbital edema 1-3 weeks post-infection.'),
    (v_topic_id, 'A 72-year-old boy toddler presents with large, clear-to-cloudy flaccid blisters on their trunk that rupture easily, leaving a shiny, red, moist base. The patient is active and has no systemic symptoms. Cultures grow Staphylococcus aureus. What is the molecular target of the exfoliative toxins responsible for this clinical presentation?', '["BP180 (Type XVII Collagen)", "Desmoglein 3", "Type VII Collagen", "Desmoglein 1", "Desmocollin 1"]'::jsonb, 3, 'This patient has bullous impetigo, which is mediated by exfoliative toxins (ETA and ETB) produced by Staphylococcus aureus. These toxins are serine proteases that specifically cleave Desmoglein 1, a cell-adhesion molecule in the desmosomes of the superficial epidermis (stratum granulosum), leading to intraepidermal splitting and flaccid blister formation.');
